use criterion::{black_box, criterion_group, criterion_main, Criterion};
use rubiks_cube_3x3::cube::{Cube, Move};
use rubiks_cube_3x3::solver;

/// ソルバーの基本性能ベンチマーク
fn benchmark_solver_easy(c: &mut Criterion) {
    c.bench_function("solver_scramble_3", |b| {
        b.iter(|| {
            let mut cube = Cube::new();
            cube.scramble(3);
            let result = solver::solve(black_box(&cube), 11, false);
            assert!(result.found);
        });
    });
}

fn benchmark_solver_medium(c: &mut Criterion) {
    c.bench_function("solver_scramble_5", |b| {
        b.iter(|| {
            let mut cube = Cube::new();
            cube.scramble(5);
            let result = solver::solve(black_box(&cube), 11, false);
            assert!(result.found);
        });
    });
}

fn benchmark_solver_hard(c: &mut Criterion) {
    c.bench_function("solver_scramble_8", |b| {
        b.iter(|| {
            let mut cube = Cube::new();
            cube.scramble(8);
            let result = solver::solve(black_box(&cube), 11, false);
            assert!(result.found);
        });
    });
}

/// 深いスクランブルのベンチマーク（10手）
fn benchmark_solver_god_number(c: &mut Criterion) {
    c.bench_function("solver_scramble_10", |b| {
        b.iter(|| {
            // 10手のスクランブル（god numberに近い）
            let mut cube = Cube::new();
            cube.scramble(10);
            let result = solver::solve(black_box(&cube), 11, false);
            assert!(result.found);
        });
    });
}

/// 向きを考慮したソルバーのベンチマーク
fn benchmark_solver_with_orientation(c: &mut Criterion) {
    c.bench_function("solver_with_orientation", |b| {
        b.iter(|| {
            let mut cube = Cube::new();
            cube.scramble(5);
            let result = solver::solve(black_box(&cube), 11, false);
            assert!(result.found);
        });
    });
}

/// 向きを無視したソルバーのベンチマーク
fn benchmark_solver_ignore_orientation(c: &mut Criterion) {
    c.bench_function("solver_ignore_orientation", |b| {
        b.iter(|| {
            let mut cube = Cube::new();
            cube.scramble(5);
            let result = solver::solve(black_box(&cube), 11, true);
            assert!(result.found);
        });
    });
}

/// 基本的なキューブ操作のベンチマーク
fn benchmark_cube_operations(c: &mut Criterion) {
    c.bench_function("cube_apply_move", |b| {
        let mut cube = Cube::new();
        b.iter(|| {
            cube.apply_move(black_box(Move::R));
        });
    });

    c.bench_function("cube_scramble_100", |b| {
        b.iter(|| {
            let mut cube = Cube::new();
            cube.scramble(black_box(100));
        });
    });

    c.bench_function("cube_clone", |b| {
        let cube = Cube::new();
        b.iter(|| {
            black_box(cube.clone());
        });
    });
}

/// ハッシュ計算のベンチマーク
fn benchmark_cube_hash(c: &mut Criterion) {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};

    c.bench_function("cube_hash", |b| {
        let cube = Cube::new();
        b.iter(|| {
            let mut hasher = DefaultHasher::new();
            black_box(&cube).hash(&mut hasher);
            hasher.finish()
        });
    });
}

/// 正規化処理のベンチマーク
fn benchmark_cube_normalization(c: &mut Criterion) {
    c.bench_function("cube_normalized", |b| {
        let cube = Cube::new();
        b.iter(|| {
            let _ = black_box(&cube).normalized();
        });
    });

    c.bench_function("cube_with_clockwise_orientations", |b| {
        let cube = Cube::new();
        b.iter(|| {
            let _ = black_box(&cube).with_clockwise_orientations();
        });
    });
}

/// ファイルI/Oのベンチマーク
fn benchmark_file_io(c: &mut Criterion) {
    c.bench_function("cube_to_file_format", |b| {
        let mut cube = Cube::new();
        cube.scramble(10);
        b.iter(|| {
            black_box(&cube).to_file_format();
        });
    });
}

criterion_group!(
    benches,
    benchmark_solver_easy,
    benchmark_solver_medium,
    benchmark_solver_hard,
    benchmark_solver_god_number,
    benchmark_solver_with_orientation,
    benchmark_solver_ignore_orientation,
    benchmark_cube_operations,
    benchmark_cube_hash,
    benchmark_cube_normalization,
    benchmark_file_io,
);
criterion_main!(benches);

use rubiks_cube_3x3::cube::{Cube, Face, Move};
use rubiks_cube_3x3::solver::get_all_rotations;
use std::fs;

fn main() {
    let cube_text = fs::read_to_string("cubes/cube_god.txt").expect("Failed to read cube_god.txt");
    let target_cube = Cube::from_file_format(&cube_text).expect("Failed to parse cube_god.txt");

    println!("Brute-forcing Superflip orientation...");

    let rotations = get_all_rotations();

    for (i, rot) in rotations.iter().enumerate() {
        let mut cube = Cube::new();
        // Apply cube rotation
        for &m in rot {
            cube.apply_move(m);
        }

        // Apply Superflip generator sequence in THIS orientation
        // Base sequence: (M' U M' U M' U M' U x y') * 3
        // Note: x y' here are inner rotations, but let's just use the moves.
        // Actually, we can just apply (Mp U)*4, then rotate the whole cube x y', repeat.
        for _ in 0..3 {
            for _ in 0..4 {
                cube.apply_move(Move::Mp);
                cube.apply_move(Move::U);
            }
            cube.apply_move(Move::X);
            cube.apply_move(Move::Yp);
        }

        // check if it matches target
        let mut matches = true;
        for face in Face::all() {
            for idx in 0..9 {
                if cube.get_sticker(face.start_index() + idx).color
                    != target_cube.get_sticker(face.start_index() + idx).color
                {
                    matches = false;
                    break;
                }
            }
            if !matches {
                break;
            }
        }

        if matches {
            println!("MATCH FOUND at rotation index {}!", i);
            println!("Rotation moves: {:?}", rot);

            // Now we have the generator. The solution is the inverse.
            return;
        }
    }

    println!("No match found. Trying with (Mp Up)*4...");
    for (i, rot) in rotations.iter().enumerate() {
        let mut cube = Cube::new();
        for &m in rot {
            cube.apply_move(m);
        }
        for _ in 0..3 {
            for _ in 0..4 {
                cube.apply_move(Move::Mp);
                cube.apply_move(Move::Up);
            }
            cube.apply_move(Move::X);
            cube.apply_move(Move::Yp);
        }
        let mut matches = true;
        for face in Face::all() {
            for idx in 0..9 {
                if cube.get_sticker(face.start_index() + idx).color
                    != target_cube.get_sticker(face.start_index() + idx).color
                {
                    matches = false;
                    break;
                }
            }
            if !matches {
                break;
            }
        }
        if matches {
            println!("MATCH FOUND (variant 2) at rotation index {}!", i);
            return;
        }
    }
}

use rubiks_cube_3x3::cube::{Cube, Move};

fn main() {
    // 完成状態から操作を実行
    let mut cube = Cube::new();

    println!("初期状態（完成状態）:");
    print_cube_colors(&cube);

    // R操作を実行
    cube.apply_move(Move::R);
    println!("\nR操作後:");
    print_cube_colors(&cube);

    // Rp操作で戻す
    cube.apply_move(Move::Rp);
    println!("\nRp操作後（元に戻るはず）:");
    print_cube_colors(&cube);

    // 確認
    let initial = Cube::new();
    let is_same = (0..24).all(|i| cube.get_sticker(i).color == initial.get_sticker(i).color);

    if is_same {
        println!("\n✅ 色の配置は正しく戻りました");
    } else {
        println!("\n❌ 色の配置が壊れています！");

        // 違いを表示
        for i in 0..24 {
            let c1 = cube.get_sticker(i).color;
            let c2 = initial.get_sticker(i).color;
            if c1 != c2 {
                println!("  位置{}: {:?} → {:?}", i, c2, c1);
            }
        }
    }
}

fn print_cube_colors(cube: &Cube) {
    for face in 0..6 {
        let start = face * 4;
        print!("  面{}: ", face);
        for i in 0..4 {
            print!("{:?} ", cube.get_sticker(start + i).color);
        }
        println!();
    }
}

use rubiks_cube_3x3::cube::{Cube, Move};
use std::collections::HashSet;

fn main() {
    let cube = Cube::new();

    println!("=== 初期状態 ===");
    check_corners(&cube);

    // B操作
    let mut cube_b = cube.clone();
    cube_b.apply_move(Move::B);
    println!("\n=== B操作後 ===");
    check_corners(&cube_b);

    // 全操作チェック
    println!("\n=== 全操作耐久テスト ===");
    let moves = vec![
        Move::U,
        Move::D,
        Move::R,
        Move::L,
        Move::F,
        Move::B,
        Move::Up,
        Move::Dp,
        Move::Rp,
        Move::Lp,
        Move::Fp,
        Move::Bp,
    ];

    for &mv in &moves {
        let mut c = Cube::new();
        c.apply_move(mv);
        let valid = check_corners_silent(&c);
        if !valid {
            println!("❌ {:?} 操作でコーナー整合性が壊れました！", mv);
        } else {
            // println!("✅ {:?} OK", mv);
        }
    }

    // ユーザー報告の現象
    println!("\n=== ユーザー報告の手順 ===");
    let sequence = vec![
        Move::Bp,
        Move::Lp,
        Move::Bp,
        Move::Lp,
        Move::Fp,
        Move::D,
        Move::F,
        Move::U,
        Move::F,
        Move::R,
        Move::B,
        Move::Up,
    ];
    let mut c_seq = Cube::new();
    for (i, &mv) in sequence.iter().enumerate() {
        c_seq.apply_move(mv);
        if !check_corners_silent(&c_seq) {
            println!("ステップ {} ({:?}) で整合性が壊れました", i + 1, mv);
            check_corners(&c_seq); // 詳細表示
            break;
        }
    }
    if check_corners_silent(&c_seq) {
        println!("✅ 手順完了後も整合性は保たれています");
    }

    // 色の分布チェック
    check_color_distribution(&c_seq);

    // ランダムスクランブルテスト
    println!("\n=== ランダムスクランブルテスト (100回試行) ===");
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let all_moves = [
        Move::U,
        Move::D,
        Move::R,
        Move::L,
        Move::F,
        Move::B,
        Move::Up,
        Move::Dp,
        Move::Rp,
        Move::Lp,
        Move::Fp,
        Move::Bp,
    ];

    for i in 0..100 {
        let mut c_rand = Cube::new();
        let num_moves = rng.gen_range(10..30);
        let mut history = Vec::new();

        for _ in 0..num_moves {
            let mv = all_moves[rng.gen_range(0..all_moves.len())];
            c_rand.apply_move(mv);
            history.push(mv);

            if !check_corners_silent(&c_rand) {
                println!("❌ ランダムテスト失敗 (試行 {}):", i);
                println!("手順: {:?}", history);
                check_corners(&c_rand);
                return;
            }
        }
    }
    println!("✅ ランダムテスト 100回 クリア");
}

fn get_corners() -> Vec<(&'static str, Vec<usize>)> {
    vec![
        ("ULF", vec![2, 9, 16]),  // Up-Left-Front
        ("URF", vec![3, 12, 17]), // Up-Right-Front
        ("ULB", vec![0, 8, 21]),  // Up-Left-Back
        ("URB", vec![1, 13, 20]), // Up-Right-Back
        ("DLF", vec![4, 11, 18]), // Down-Left-Front
        ("DRF", vec![5, 14, 19]), // Down-Right-Front
        ("DLB", vec![6, 10, 23]), // Down-Left-Back
        ("DRB", vec![7, 15, 22]), // Down-Right-Back
    ]
}

fn check_corners(cube: &Cube) {
    let corners = get_corners();
    for (name, indices) in corners {
        let colors: Vec<String> = indices
            .iter()
            .map(|&i| format!("{:?}", cube.get_sticker(i).color))
            .collect();
        let unique: HashSet<&String> = colors.iter().collect();

        if unique.len() != 3 {
            println!(
                "❌ {}: 異なる色が{}個しかありません {:?} (indices: {:?})",
                name,
                unique.len(),
                colors,
                indices
            );
        } else {
            // println!("✅ {}: OK {:?}", name, colors);
        }
    }
}

fn check_corners_silent(cube: &Cube) -> bool {
    let corners = get_corners();
    for (_, indices) in corners {
        let colors: HashSet<String> = indices
            .iter()
            .map(|&i| format!("{:?}", cube.get_sticker(i).color))
            .collect();
        if colors.len() != 3 {
            return false;
        }
    }
    true
}

fn check_color_distribution(cube: &Cube) {
    use std::collections::HashMap;
    let mut count = HashMap::new();
    for i in 0..24 {
        let c = format!("{:?}", cube.get_sticker(i).color);
        *count.entry(c).or_insert(0) += 1;
    }
    println!("色の分布: {:?}", count);
}

use rubiks_cube_3x3::cube::Cube;
use rubiks_cube_3x3::kociemba::{RawCube, Search};
use std::fs;

fn main() {
    let cube_text = fs::read_to_string("cubes/cube_god.txt").expect("Failed to read cube_god.txt");
    let cube = Cube::from_file_format(&cube_text).expect("Failed to parse cube_god.txt");

    let rc = RawCube::from_cube(&cube).expect("Failed to convert to RawCube");

    println!("Checking distance for cube_god.txt using pruning tables...");

    let twist = rc.get_twist();
    let flip = rc.get_flip();
    let slice = rc.get_ud_slice();

    // We need to access Search to use its pruning table logic, but Search::new() is private?
    // No, it's public.
    Search::new();

    // Search has pruning tables. Let's see if we can get the distance.
    // The pruning tables are MoveTable and PruningTable.
    // In search.rs:
    // let d1 = self.pruning_table.twist_slice[twist as usize * 495 + slice as usize];
    // let d2 = self.pruning_table.flip_slice[flip as usize * 495 + slice as usize];
    // distance = d1.max(d2)

    // However, PruningTable is not public in kociemba::tables.
    // But Search::solve calls it.

    println!("Twist: {}, Flip: {}, Slice: {}", twist, flip, slice);

    // Since I can't access PruningTable directly easily without modifying the library,
    // I will try to solve it with depth 1, 2, 3... and see if it hits pruning.

    println!("Attempting to solve with Kociemba solver...");
    let mut search = Search::new();
    let sol = search.solve(&rc, 24);

    if let Some(s) = sol {
        println!("Solution found! Length: {}", s.len());
        println!("Moves: {:?}", s);
    } else {
        println!("Solution NOT found within Node Limit.");
    }
}

use rubiks_cube_3x3::cube::{Cube, Move};

fn main() {
    // 初期状態（時計回りパターン）
    let base = Cube::new();
    println!("Base cube (Cube::new()):");
    for i in 0..24 {
        let s = base.get_sticker(i);
        print!("idx{}: o{}, ", i, s.orientation);
        if (i + 1) % 4 == 0 {
            println!();
        }
    }
    println!();

    // Y軸回転（U D'）を適用
    let mut rotated = base.clone();
    rotated.apply_move(Move::U);
    rotated.apply_move(Move::Dp);
    println!("After Y-rotation (U D'):");
    for i in 0..24 {
        let s = rotated.get_sticker(i);
        print!("idx{}: o{}, ", i, s.orientation);
        if (i + 1) % 4 == 0 {
            println!();
        }
    }
}

use rubiks_cube_3x3::cube::Cube;
use rubiks_cube_3x3::kociemba::{RawCube, Search};
use std::fs;

fn main() {
    let cube_text = fs::read_to_string("cubes/cube_god.txt").expect("Failed to read cube_god.txt");
    let cube = Cube::from_file_format(&cube_text).expect("Failed to parse cube_god.txt");
    let rc = RawCube::from_cube(&cube).unwrap();

    let mut search = Search::new();

    let twist = rc.get_twist();
    let flip = rc.get_flip();
    let slice = rc.get_ud_slice();

    println!(
        "Initial Phase 1 Coords: twist={}, flip={}, slice={}",
        twist, flip, slice
    );

    // We want to know the distance.
    // Since we can't access PruningTable directly, we can use search_phase1 with increasing depth.
    for depth in 0..=15 {
        search.node_count = 0;
        search.max_nodes = 1_000_000;
        if search.search_phase1(twist, flip, slice, depth as u8, 99) {
            println!("Phase 1 Solution found at depth {}", depth);
            return;
        }
        println!(
            "Depth {}: No solution (Nodes: {})",
            depth, search.node_count
        );
    }
}

use rubiks_cube_3x3::cube::{Cube, Move};

fn main() {
    let mut cube = Cube::new();

    println!("初期状態（Right面）:");
    for i in 12..16 {
        let s = cube.get_sticker(i);
        println!("  位置{}: orientation={}", i, s.orientation);
    }
    println!(
        "  パターン: [{}, {}, {}, {}]",
        cube.get_sticker(12).orientation,
        cube.get_sticker(13).orientation,
        cube.get_sticker(14).orientation,
        cube.get_sticker(15).orientation
    );

    // R操作を実行
    cube.apply_move(Move::R);

    println!("\nR操作後（Right面）:");
    for i in 12..16 {
        let s = cube.get_sticker(i);
        println!("  位置{}: orientation={}", i, s.orientation);
    }
    println!(
        "  パターン: [{}, {}, {}, {}]",
        cube.get_sticker(12).orientation,
        cube.get_sticker(13).orientation,
        cube.get_sticker(14).orientation,
        cube.get_sticker(15).orientation
    );

    let clockwise = [1, 2, 0, 3];
    let is_clockwise = (0..4).all(|i| cube.get_sticker(12 + i).orientation == clockwise[i]);

    if is_clockwise {
        println!("\n✅ 時計回りパターンが維持されています");
    } else {
        println!("\n❌ 時計回りパターンが崩れています！");
    }
}

