        Move::Rp,
        Move::L,
        Move::B2,
        Move::U2,
        Move::F2,
    ];

    let mut cube = Cube::new();
    // Superflip depends on having centers right. Cube::new() has standard centers.
    for &mv in &moves {
        cube.apply_move(mv);
    }

    println!("Applied Superflip sequence to solved cube.");
    println!("Is solved (colors)? {}", cube.is_solved());

