            if i < 11 {
                print!(", ");
            }
        }
        println!("],");

        print!("        eo: [");
        for (i, eo) in rc.eo.iter().enumerate() {
            print!("{}", eo);
            if i < 11 {
                print!(", ");
            }
        }
        println!("],");
        println!("    }},");
    }
    println!("];");
}

