use super::{Color, Cube};
use crate::error::{CubeError, Result};

/// キューブの状態をファイル形式の文字列に変換
/// 形式: 各ステッカーを1文字で表現（例: W, G, .）
pub fn to_file_format(cube: &Cube) -> String {
    let mut result = String::new();

    // ヘルパー関数：面の情報を取得
    let get_face = |face_idx: usize| -> String {
        let start = face_idx * crate::cube::STICKERS_PER_FACE;
        let mut face_str = String::new();
        for i in 0..crate::cube::STICKERS_PER_FACE {
            let sticker = cube.stickers[start + i];
            let c = match sticker.color {
                Color::White => 'W',
                Color::Yellow => 'Y',
                Color::Green => 'G',
                Color::Blue => 'B',
                Color::Red => 'R',
                Color::Orange => 'O',
                Color::Gray => '.', // 未設定はドット
            };
            face_str.push(c);
        }
        face_str
    };

    // 展開図形式で出力
    // 1行目: Up
    result.push_str("          ");
    result.push_str(&get_face(0)); // Up
    result.push('\n');

    // 2行目: Left Front Right Back
    result.push_str(&get_face(2)); // Left
    result.push(' ');
    result.push_str(&get_face(4)); // Front
    result.push(' ');
    result.push_str(&get_face(3)); // Right
    result.push(' ');
    result.push_str(&get_face(5)); // Back
    result.push('\n');

    // 3行目: Down
    result.push_str("          ");
    result.push_str(&get_face(1)); // Down
    result.push('\n');

    result
}

/// ファイル形式の文字列からキューブを作成
pub fn from_file_format(s: &str) -> Result<Cube> {
    let lines: Vec<&str> = s.lines().collect();

    if lines.len() != 3 {
        return Err(CubeError::InvalidFormat(format!(
            "3行必要ですが{}行しかありません",
            lines.len()
        )));
    }

    // 色を解析
    let parse_colors = |s: &str| -> Result<Vec<Color>> {
        s.chars()
            .filter(|c| !c.is_whitespace())
            .map(|c| match c.to_ascii_uppercase() {
                'W' => Ok(Color::White),
                'Y' => Ok(Color::Yellow),
                'G' => Ok(Color::Green),
                'B' => Ok(Color::Blue),
                'R' => Ok(Color::Red),
                'O' => Ok(Color::Orange),
                '.' => Ok(Color::Gray),
                _ => Err(CubeError::InvalidColorChar(c)),
            })
            .collect()
    };

    // 各行から色を取得
    let line1_colors = parse_colors(lines[0])?;
    let line2_colors = parse_colors(lines[1])?;
    let line3_colors = parse_colors(lines[2])?;

    // 検証
    if line1_colors.len() != 9 {
        return Err(CubeError::InvalidFormat(format!(
            "1行目: 9ステッカー必要ですが{}個です",
            line1_colors.len()
        )));
    }
    if line2_colors.len() != 36 {
        return Err(CubeError::InvalidFormat(format!(
            "2行目: 36ステッカー必要ですが{}個です",
            line2_colors.len()
        )));
    }
    if line3_colors.len() != 9 {
        return Err(CubeError::InvalidFormat(format!(
            "3行目: 9ステッカー必要ですが{}個です",
            line3_colors.len()
        )));
    }

    // 24色の配列を作成（内部順序: Up, Down, Left, Right, Front, Back）

    // 各面の配置ルール: (面、ソースとなる色のスライス)
    const SPF: usize = crate::cube::STICKERS_PER_FACE;
    use crate::cube::{Face, Sticker};
    let mut stickers = [Sticker::new(Color::White); crate::cube::NUM_STICKERS];

    let mut map_face = |face: Face, line_colors: &[Color]| {
        let start = face.start_index();
        for i in 0..SPF {
            stickers[start + i] = Sticker::new(line_colors[i]);
        }
    };

    map_face(Face::Up, &line1_colors);
    map_face(Face::Down, &line3_colors);
    map_face(Face::Left, &line2_colors[0..9]);
    map_face(Face::Front, &line2_colors[9..18]);
    map_face(Face::Right, &line2_colors[18..27]);
    map_face(Face::Back, &line2_colors[27..36]);

    let mut cube = Cube {
        stickers,
        pieces: crate::cube::piece::get_initial_pieces(),
    };

    // スキャン途中（Grayあり）でない場合は、向きを初期化し、ピースモデルを復元
    let has_gray = cube.stickers.iter().any(|s| s.color == Color::Gray);
    if !has_gray {
        // 各ピースの位置と回転を色から物理的に正しく復元
        cube.restore_orientation_instantly()?;
    }

    Ok(cube)
}

pub mod enums;
pub mod io;
pub mod piece;
pub mod rotation;
pub mod validation;

pub use self::enums::{Color, Face, Move, Sticker, NUM_STICKERS, STICKERS_PER_FACE};

/// 完成状態における標準的なステッカーの向きパターン。
pub const CLOCKWISE_ORIENTATION_PATTERN: [u8; 9] = [0; 9];

/// 3x3 ルービックキューブを表す構造体。
///
/// 54枚のステッカー（[`Sticker`]）をフラットな配列として保持します。
/// 内部構造は面の順序と各面内のインデックスによって定義されます。
#[derive(Debug, Clone)]
pub struct Cube {
    pub stickers: [Sticker; 54],
    pub pieces: [piece::Cubie; 26],
}

impl PartialEq for Cube {
    fn eq(&self, other: &Self) -> bool {
        self.stickers == other.stickers
    }
}

impl Eq for Cube {}

impl std::hash::Hash for Cube {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.stickers.hash(state);
    }
}

impl Cube {
    #[must_use]
    pub fn new() -> Self {
        let stickers = [Sticker::new(Color::White); NUM_STICKERS];
        let pieces = piece::get_initial_pieces();
        let mut cube = Self { stickers, pieces };
        cube.sync_stickers();
        cube
    }

    /// ピースの状態からステッカー配列を更新します。
    pub fn sync_stickers(&mut self) {
        for p in &self.pieces {
            p.project_to_stickers(&mut self.stickers);
        }
    }

    /// 各面のステッカーの色がすべて一致しているか（完成しているか）を判定します。
    ///
    /// ステッカー自体の向き（矢印などの方向）は無視されます。
    ///
    /// # 戻り値
    ///
    /// すべての面が単色であれば `true` を返します。
    #[must_use]
    pub fn is_solved(&self) -> bool {
        for face in Face::all() {
            let face_start = face.start_index();
            let color = self.stickers[face_start].color;
            for i in 1..STICKERS_PER_FACE {
                if self.stickers[face_start + i].color != color {
                    return false;
                }
            }
        }
        true
    }

    /// 色が揃っており、かつステッカーの向きも初期状態と同じであるかを判定します。
    ///
    /// # 戻り値
    ///
    /// 色と向きの両方が初期状態と一致していれば `true` を返します。
    #[must_use]
    pub fn is_solved_with_orientation(&self) -> bool {
        if !self.is_solved() {
            return false;
        }
        for face in Face::all() {
            let start = face.start_index();
            for (i, &expected_orientation) in CLOCKWISE_ORIENTATION_PATTERN.iter().enumerate() {
                if self.stickers[start + i].orientation != expected_orientation {
                    return false;
                }
            }
        }
        true
    }

    /// 指定した絶対インデックス（0-23）のステッカーを取得します。
    #[must_use]
    pub fn get_sticker(&self, index: usize) -> Sticker {
        self.stickers[index]
    }

    /// 指定した絶対インデックスのステッカーの色を設定します。
    ///
    /// 色を変更すると、そのステッカーの向き（orientation）は 0 にリセットされます。
    pub fn set_sticker_color(&mut self, index: usize, color: Color) {
        self.stickers[index].color = color;
        // 向きはリセット（手動入力時は向きを0にする）
        self.stickers[index].orientation = 0;
    }

    /// 各ステッカーの色を維持したまま、向き情報のみを標準的な時計回りパターンにリセットした新しいキューブを返します。
    ///
    /// ソルバーで色のみを解いた後に、物理的に正しい向きを再設定する場合などに使用されます。
    #[must_use]
    pub fn with_clockwise_orientations(&self) -> Self {
        let mut new_cube = self.clone();

        for face in Face::all() {
            let face_start = face.start_index();
            for (offset, &pattern) in CLOCKWISE_ORIENTATION_PATTERN.iter().enumerate() {
                let idx = face_start + offset;
                new_cube.stickers[idx].orientation = pattern;
            }
        }

        new_cube
    }

    /// 54個の色配列から新しいキューブを作成します（物理的な向きを自動復元）。
    ///
    /// 色の配置が物理的に可能でない場合はエラーを返します。
    pub fn from_colors(colors: &[Color; 54]) -> crate::error::Result<Self> {
        let mut stickers = [Sticker::new(Color::White); 54];
        for (i, &color) in colors.iter().enumerate() {
            stickers[i] = Sticker {
                color,
                orientation: 0, // 一時的に0で初期化
            };
        }

        let mut cube = Cube {
            stickers,
            pieces: piece::get_initial_pieces(),
        };
        // Call the static validate_colors method
        Self::validate_colors(colors)?;

        // 3色から物理的に正しい向きを復元
        cube.restore_orientation_instantly()?;

        Ok(cube)
    }

    /// 指定された色配列（54要素）がキューブとして妥当であるかを検証します。
    pub fn validate_colors(colors: &[Color; 54]) -> crate::error::Result<()> {
        validation::validate_colors(colors)
    }

    /// キューブの現在の状態（色と向きの組み合わせ）が、物理的に到達可能な有効な状態であるかを判定します。
    pub fn is_valid_state(&self) -> crate::error::Result<()> {
        validation::is_valid_state(self)
    }

    /// キューブの現在の内容を、ファイル保存用のテキスト形式に変換します。
    pub fn to_file_format(&self) -> String {
        io::to_file_format(self)
    }

    /// ファイル保存形式の文字列をパースして、新しいキューブを作成します。
    pub fn from_file_format(s: &str) -> crate::error::Result<Self> {
        io::from_file_format(s)
    }

    /// 回転操作を適用します。
    pub fn apply_move(&mut self, mv: Move) {
        rotation::apply_move(self, mv);
    }

    /// 指定回数のランダムな回転操作を適用します。
    pub fn scramble(&mut self, moves: usize) {
        rotation::scramble(self, moves);
    }

    /// 現在の色配置に基づいて、物理的に正しいステッカー向（twist）を瞬時に復元します。
    ///
    /// 各コーナーピースの3色の配置を、24通りの完成状態のいずれかと照合することで、
    /// 探索を行わずに正しい向きを特定します。
    ///
    /// # エラー
    ///
    /// 各ステッカーの色情報から、ピースの位置と回転を物理的に正しい状態に復元します。
    pub fn restore_orientation_instantly(&mut self) -> crate::error::Result<()> {
        // 色の妥当性チェック
        let mut colors_array = [Color::White; 54];
        for (i, color) in colors_array.iter_mut().enumerate() {
            *color = self.stickers[i].color;
        }
        Self::validate_colors(&colors_array)?;

        use crate::cube::validation::{CENTER_STICKERS, CORNER_STICKERS, EDGE_STICKERS};

        // 24通りの完成状態（全方位）を取得
        let solved_states = crate::solver::get_solved_states();
        let mut new_pieces_vec = Vec::new();

        // 1. まずセンターの位置関係から、現在の「全体の方位」を特定する。
        //    センターのみが完全に一致する solved_state を探す。
        let mut preferred_state_idx = 0;
        let mut found_preferred = false;
        for (idx, solved) in solved_states.iter().enumerate() {
            let mut centers_match = true;
            for &c_idx in &CENTER_STICKERS {
                if self.stickers[c_idx].color != solved.stickers[c_idx].color {
                    centers_match = false;
                    break;
                }
            }
            if centers_match {
                preferred_state_idx = idx;
                found_preferred = true;
                break;
            }
        }

        if !found_preferred {
            return Err(crate::error::CubeError::InvalidState(
                "中心ピースの色配置が不正です".to_string(),
            ));
        }
        let preferred_state = &solved_states[preferred_state_idx];

        if !preferred_state.is_solved_with_orientation() {
            return Err(crate::error::CubeError::InvalidState(
                "内部解決状態の不整合".to_string(),
            ));
        }

        // 2. 特定された preferred_state に基づいてセンターピースを復元
        for &idx in &CENTER_STICKERS {
            self.restore_piece_at_slot(
                &[idx],
                std::slice::from_ref(preferred_state),
                &mut new_pieces_vec,
            )?;
        }

        // 3. コーナーとエッジを復元（これらは色情報から物理的に一義的に決まる）
        // コーナー (8個)
        for &slot_indices in &CORNER_STICKERS {
            self.restore_piece_at_slot(&slot_indices, solved_states, &mut new_pieces_vec)?;
        }

        // エッジ (12個)
        for &slot_indices in &EDGE_STICKERS {
            self.restore_piece_at_slot(&slot_indices, solved_states, &mut new_pieces_vec)?;
        }

        if new_pieces_vec.len() != 26 {
            return Err(crate::error::CubeError::InvalidState(format!(
                "ピースの復元に失敗しました（計{}個）",
                new_pieces_vec.len()
            )));
        }

        // pieces 配列を更新
        self.pieces = new_pieces_vec.try_into().map_err(|_| {
            crate::error::CubeError::InvalidState("ピース配列の変換に失敗しました".to_string())
        })?;

        // 最後に pieces の状態を stickers (特に orientation) に反映
        self.sync_stickers();

        // 最終的なチェック
        self.is_valid_state()
    }

    /// 特定のスロットにあるピースを、 solved_states を利用して復元します。
    fn restore_piece_at_slot(
        &self,
        slot_indices: &[usize],
        solved_states: &[Cube],
        target_pieces: &mut Vec<piece::Cubie>,
    ) -> crate::error::Result<()> {
        let current_colors: Vec<Color> = slot_indices
            .iter()
            .map(|&idx| self.stickers[idx].color)
            .collect();

        for solved in solved_states {
            let solved_colors: Vec<Color> = slot_indices
                .iter()
                .map(|&idx| solved.stickers[idx].color)
                .collect();

            if current_colors == solved_colors {
                // どのステッカーも同じピースに属しているはずなので、slot_indices[0] を使ってピースを特定する
                let test_idx = slot_indices[0];

                // solved.pieces を探索して、test_idx にステッカーを投影するピースを探す
                for p in &solved.pieces {
                    let mut temp_stickers = [Sticker::new(Color::Gray); NUM_STICKERS];
                    p.project_to_stickers(&mut temp_stickers);
                    if temp_stickers[test_idx].color != Color::Gray {
                        // 見つけた！(位置も回転も solved Cube のものが現在のスロットの状態を正しく表している)
                        target_pieces.push(p.clone());
                        return Ok(());
                    }
                }
            }
        }

        Err(crate::error::CubeError::InvalidState(format!(
            "指定された色の組み合わせを持つピースが見つかりません: {:?}",
            current_colors
        )))
    }

    /// ソルバーで見つかった解を利用して向きを復元します（現在は内部で `restore_orientation_instantly` を呼び出します）。
    pub fn apply_orientation_solution(
        &mut self,
        _solution: &crate::solver::Solution,
    ) -> crate::error::Result<()> {
        self.restore_orientation_instantly()
    }

    /// ステッカー配列に設定された中央方位（orientation）情報を、内部のピース状態に強制的に同期させます。
    ///
    /// 通常、`apply_move` を呼ぶとピースの状態からステッカーが再生成されますが、
    /// テストなどでステッカーの方位を直接書き換えた場合、このメソッドを呼ぶことで
    /// その方位を物理的なピースの回転状態として定着させることができます。
    pub fn force_sync_orientation_to_pieces(&mut self) {
        use crate::cube::validation::CENTER_STICKERS;

        for &idx in &CENTER_STICKERS {
            let ori = self.stickers[idx].orientation;
            if ori == 0 {
                continue;
            }

            // 該当するセンターピースを見つける
            let target_color = self.stickers[idx].color;
            for p in &mut self.pieces {
                if p.piece_type == crate::cube::piece::PieceType::Center
                    && p.stickers[0].color == target_color
                {
                    // センターピースの向きを更新する
                    // calculate_orientation の逆関数的な動作が必要。
                    // 0 -> 単位行列
                    // 1 -> 軸を中心に時計回り 90度
                    // 2 -> 180度
                    // 3 -> 反時計回り 90度

                    let normal = p.stickers[0].initial_normal;
                    let angle = match ori {
                        1 => -std::f32::consts::FRAC_PI_2, // CW
                        2 => std::f32::consts::PI,         // 180
                        3 => std::f32::consts::FRAC_PI_2,  // CCW
                        _ => 0.0,
                    };

                    // 現在の回転をリセットして、指定された方位に設定する
                    // (注意: このメソッドは「色が揃っている解決状態」付近での使用を想定している)
                    p.current_rot = glam::Mat4::from_axis_angle(normal, angle);
                    break;
                }
            }
        }
        // pieces を更新したので、再度 stickers に反映（整合性確保）
        self.sync_stickers();
    }

    /// 各ステッカーの向き情報をリセット（0に設定）したキューブの複製を返します。
    ///
    /// ハッシュマップやセットで、向きによらず「色の配置」のみで状態を管理したい場合に使用します。
    #[must_use]
    pub fn normalized(&self) -> Self {
        let mut new_cube = self.clone();
        for sticker in &mut new_cube.stickers {
            sticker.orientation = 0;
        }
        new_cube
    }
}

impl Default for Cube {
    fn default() -> Self {
        Self::new()
    }
}

use crate::cube::{Color, Face, Sticker};
use glam::{Mat4, Vec3};

/// ピース（キューブレット）のタイプ
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PieceType {
    Center,
    Edge,
    Corner,
}

/// ピース上の個々のステッカーの色と初期法線
#[derive(Debug, Clone, Copy)]
pub struct CubieSticker {
    pub initial_normal: Vec3,
    pub color: Color,
}

/// ルービックキューブを構成する26個のピース（センター中の1つを除く）
#[derive(Debug, Clone)]
pub struct Cubie {
    pub piece_type: PieceType,
    pub initial_pos: Vec3,
    pub current_pos: Vec3,
    pub current_rot: Mat4,
    pub stickers: Vec<CubieSticker>,
}

impl Cubie {
    pub fn new(pos: Vec3, stickers: Vec<CubieSticker>) -> Self {
        let piece_type = match stickers.len() {
            1 => PieceType::Center,
            2 => PieceType::Edge,
            3 => PieceType::Corner,
            _ => panic!("Invalid number of stickers for a piece: {}", stickers.len()),
        };

        Self {
            piece_type,
            initial_pos: pos,
            current_pos: pos,
            current_rot: Mat4::IDENTITY,
            stickers,
        }
    }

    /// ピースを特定の軸を中心に指定された角度だけ回転させます。
    pub fn rotate(&mut self, axis: Vec3, angle_rad: f32) {
        let rot_mat = Mat4::from_axis_angle(axis, angle_rad);

        // 位置の更新 (浮動小数点の誤差を丸める)
        let new_pos = rot_mat.transform_point3(self.current_pos);
        self.current_pos = Vec3::new(new_pos.x.round(), new_pos.y.round(), new_pos.z.round());

        // 回転状態の更新
        self.current_rot = rot_mat * self.current_rot;
    }

    /// このピースが持つステッカーを、現在の回転状態に基づいて Facelet 配列（54枚）に投影します。
    pub fn project_to_stickers(&self, target: &mut [Sticker; 54]) {
        for cubie_sticker in &self.stickers {
            // 現在の法線を計算
            let current_normal = self
                .current_rot
                .transform_vector3(cubie_sticker.initial_normal);
            let n = Vec3::new(
                current_normal.x.round(),
                current_normal.y.round(),
                current_normal.z.round(),
            );

            // どの面に属するか特定
            let face = if n.y > 0.5 {
                Face::Up
            } else if n.y < -0.5 {
                Face::Down
            } else if n.x < -0.5 {
                Face::Left
            } else if n.x > 0.5 {
                Face::Right
            } else if n.z > 0.5 {
                Face::Front
            } else if n.z < -0.5 {
                Face::Back
            } else {
                continue; // 内部に向いている面（通常はないはず）
            };

            // その面内でのインデックスを計算
            let face_idx = face_to_local_index(face, self.current_pos);
            let abs_idx = face.start_index() + face_idx;

            // ステッカーの「向き (orientation)」を計算
            // Piece の rotation 行列から、どの程度自転しているかを導出
            let ori = self.calculate_orientation(cubie_sticker.initial_normal, n);

            target[abs_idx] = Sticker {
                color: cubie_sticker.color,
                orientation: ori,
            };
        }
    }

    /// ステッカーの piece 内での向きを 0-3 で計算します。
    pub fn calculate_orientation(&self, initial_normal: Vec3, current_normal: Vec3) -> u8 {
        calculate_orientation_with_rot(initial_normal, current_normal, self.current_rot)
    }

    /// 与えられた色（順序不同）をすべて持っているピースかどうか判定します。
    pub fn matches_colors(&self, target_colors: &[Color]) -> bool {
        if self.stickers.len() != target_colors.len() {
            return false;
        }
        let mut available_colors: Vec<Color> = self.stickers.iter().map(|s| s.color).collect();
        for &tc in target_colors {
            if let Some(pos) = available_colors.iter().position(|&c| c == tc) {
                available_colors.remove(pos);
            } else {
                return false;
            }
        }
        true
    }
}

/// 指定された回転行列に基づいて向きを計算します（アニメーション用）。
pub fn calculate_orientation_with_rot(
    _initial_normal: Vec3,
    current_normal: Vec3,
    rot: Mat4,
) -> u8 {
    let current_v_base = get_face_up_axis(current_normal);

    // ピースの初期「上」方向（Whiteステッカーなら -Z等）が、今の回転行列でどこを向いているか
    // すべてのステッカーについて、初期状態 (rot=IDENTITY) での initial_normal 方向の面において
    // get_face_up_axis(initial_normal) が「上 (orientation=0)」を指していると仮定する。
    // しかし、Cubie には複数のステッカーがあるので、各ステッカーごとに初期の上方向が異なる。

    // 正しいアプローチ: 各ステッカーの initial_normal に対応する initial_v_base を求める。
    let initial_v_base = get_face_up_axis(_initial_normal);
    let actual_v = rot.transform_vector3(initial_v_base);

    // actual_v と、現在の面の基準上方向 current_v_base のズレを計算する。
    let dot = actual_v.dot(current_v_base);
    if dot > 0.9 {
        0
    } else if dot < -0.9 {
        2
    } else {
        let cross = current_v_base.cross(actual_v);
        if cross.dot(current_normal) > 0.9 {
            3 // CCW
        } else {
            1 // CW
        }
    }
}

/// 面と空間座標から、面内の 0-8 のインデックスを返します。
pub fn face_to_local_index(face: Face, pos: Vec3) -> usize {
    match face {
        Face::Up => {
            let col = (pos.x + 1.0) as usize;
            let row = (pos.z + 1.0) as usize;
            row * 3 + col
        }
        Face::Down => {
            let col = (pos.x + 1.0) as usize;
            let row = (1.0 - pos.z) as usize;
            row * 3 + col
        }
        Face::Left => {
            let col = (pos.z + 1.0) as usize;
            let row = (1.0 - pos.y) as usize;
            row * 3 + col
        }
        Face::Right => {
            let col = (1.0 - pos.z) as usize;
            let row = (1.0 - pos.y) as usize;
            row * 3 + col
        }
        Face::Front => {
            let col = (pos.x + 1.0) as usize;
            let row = (1.0 - pos.y) as usize;
            row * 3 + col
        }
        Face::Back => {
            let col = (1.0 - pos.x) as usize;
            let row = (1.0 - pos.y) as usize;
            row * 3 + col
        }
    }
}

/// 各面の「上」方向（orientation=0 の基準）を定義します。
/// 展開図の接続 (U <-> B, B <-> D) がスムーズになるように定義。
fn get_face_up_axis(normal: Vec3) -> Vec3 {
    let n = Vec3::new(normal.x.round(), normal.y.round(), normal.z.round());
    if n == Vec3::Y {
        -Vec3::Z // U
    } else if n == -Vec3::Y {
        Vec3::Z // D
    } else {
        Vec3::Y // L, R, F, B
    }
}

/// 全26個のピースを初期完成状態で生成します。
pub fn get_initial_pieces() -> [Cubie; 26] {
    let mut pieces = Vec::new();

    // -1, 0, 1 の全組み合わせ（(0,0,0)を除く）
    for x in -1..=1 {
        for y in -1..=1 {
            for z in -1..=1 {
                if x == 0 && y == 0 && z == 0 {
                    continue;
                }

                let pos = Vec3::new(x as f32, y as f32, z as f32);
                let mut stickers = Vec::new();

                // 各座標が面の境界にある場合、ステッカーを追加
                if x == 1 {
                    stickers.push(CubieSticker {
                        initial_normal: Vec3::X,
                        color: Color::Blue,
                    });
                }
                if x == -1 {
                    stickers.push(CubieSticker {
                        initial_normal: -Vec3::X,
                        color: Color::Green,
                    });
                }
                if y == 1 {
                    stickers.push(CubieSticker {
                        initial_normal: Vec3::Y,
                        color: Color::White,
                    });
                }
                if y == -1 {
                    stickers.push(CubieSticker {
                        initial_normal: -Vec3::Y,
                        color: Color::Yellow,
                    });
                }
                if z == 1 {
                    stickers.push(CubieSticker {
                        initial_normal: Vec3::Z,
                        color: Color::Red,
                    });
                }
                if z == -1 {
                    stickers.push(CubieSticker {
                        initial_normal: -Vec3::Z,
                        color: Color::Orange,
                    });
                }

                pieces.push(Cubie::new(pos, stickers));
            }
        }
    }

    pieces.try_into().expect("Must have 26 pieces")
}

use super::{Cube, Move};
use glam::Vec3;

/// 指定された回転操作をキューブに適用します。
pub fn apply_move(cube: &mut Cube, mv: Move) {
    let (axis, layer_val, angle) = move_to_geometric_params(mv);

    // 全体回転 (X, Y, Z) の場合は全ピースを対象にする
    let is_global = matches!(
        mv,
        Move::X
            | Move::Xp
            | Move::X2
            | Move::Y
            | Move::Yp
            | Move::Y2
            | Move::Z
            | Move::Zp
            | Move::Z2
    );

    for piece in &mut cube.pieces {
        if is_global || is_in_layer(piece.current_pos, axis, layer_val) {
            piece.rotate(axis, angle);
        }
    }

    // ピースの状態を Facelet（ステッカー）配列に反映
    cube.sync_stickers();
}

/// 指定回数のランダムな回転操作を適用します。
pub fn scramble(cube: &mut Cube, moves: usize) {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let all_moves: Vec<Move> = Move::all_moves()
        .into_iter()
        .filter(|m| !m.is_global() && !m.is_middle_layer())
        .collect();

    for _ in 0..moves {
        let mv = all_moves[rng.gen_range(0..all_moves.len())];
        apply_move(cube, mv);
    }
}

/// 操作を幾何学的なパラメータ（回転軸、対象層、角度）に変換します。
fn move_to_geometric_params(mv: Move) -> (Vec3, i8, f32) {
    let pi_2 = std::f32::consts::FRAC_PI_2;
    match mv {
        // R層 (x = 1)
        Move::R => (Vec3::X, 1, -pi_2),
        Move::Rp => (Vec3::X, 1, pi_2),
        Move::R2 => (Vec3::X, 1, pi_2 * 2.0),
        // L層 (x = -1)
        Move::L => (Vec3::X, -1, pi_2),
        Move::Lp => (Vec3::X, -1, -pi_2),
        Move::L2 => (Vec3::X, -1, pi_2 * 2.0),
        // M層 (x = 0) - Lと同じ回転方向
        Move::M => (Vec3::X, 0, pi_2),
        Move::Mp => (Vec3::X, 0, -pi_2),
        Move::M2 => (Vec3::X, 0, pi_2 * 2.0),

        // U層 (y = 1)
        Move::U => (Vec3::Y, 1, -pi_2),
        Move::Up => (Vec3::Y, 1, pi_2),
        Move::U2 => (Vec3::Y, 1, pi_2 * 2.0),
        // D層 (y = -1)
        Move::D => (Vec3::Y, -1, pi_2),
        Move::Dp => (Vec3::Y, -1, -pi_2),
        Move::D2 => (Vec3::Y, -1, pi_2 * 2.0),
        // E層 (y = 0) - Dと同じ回転方向
        Move::E => (Vec3::Y, 0, pi_2),
        Move::Ep => (Vec3::Y, 0, -pi_2),
        Move::E2 => (Vec3::Y, 0, pi_2 * 2.0),

        // F層 (z = 1)
        Move::F => (Vec3::Z, 1, -pi_2),
        Move::Fp => (Vec3::Z, 1, pi_2),
        Move::F2 => (Vec3::Z, 1, pi_2 * 2.0),
        // B層 (z = -1)
        Move::B => (Vec3::Z, -1, pi_2),
        Move::Bp => (Vec3::Z, -1, -pi_2),
        Move::B2 => (Vec3::Z, -1, pi_2 * 2.0),
        // S層 (z = 0) - Fと同じ回転方向
        Move::S => (Vec3::Z, 0, -pi_2),
        Move::Sp => (Vec3::Z, 0, pi_2),
        Move::S2 => (Vec3::Z, 0, pi_2 * 2.0),

        // 全体 X
        Move::X => (Vec3::X, 2, -pi_2),
        Move::Xp => (Vec3::X, 2, pi_2),
        Move::X2 => (Vec3::X, 2, pi_2 * 2.0),
        // 全体 Y
        Move::Y => (Vec3::Y, 2, -pi_2),
        Move::Yp => (Vec3::Y, 2, pi_2),
        Move::Y2 => (Vec3::Y, 2, pi_2 * 2.0),
        // 全体 Z
        Move::Z => (Vec3::Z, 2, -pi_2),
        Move::Zp => (Vec3::Z, 2, pi_2),
        Move::Z2 => (Vec3::Z, 2, pi_2 * 2.0),
    }
}

/// ピースがある回転軸上の指定された層に含まれるか判定します。
fn is_in_layer(pos: Vec3, axis: Vec3, layer_val: i8) -> bool {
    if axis == Vec3::X {
        (pos.x.round() as i8) == layer_val
    } else if axis == Vec3::Y {
        (pos.y.round() as i8) == layer_val
    } else if axis == Vec3::Z {
        (pos.z.round() as i8) == layer_val
    } else {
        false
    }
}

use super::{Color, Cube};
use crate::error::{CubeError, Result};

/// 色配列の妥当性をチェックします。
///
/// 各色が正確に9つずつ存在するかを確認します。
pub fn validate_colors(colors: &[Color; crate::cube::NUM_STICKERS]) -> Result<()> {
    let mut counts = [0usize; 7]; // Color Enum の数に合わせて7 (Grayを含む)
    for &color in colors {
        let idx = color as usize;
        if idx < 7 {
            counts[idx] += 1;
        }
    }

    // 各色が9つずつあるかチェック
    let expected_colors = [
        Color::White,
        Color::Yellow,
        Color::Green,
        Color::Blue,
        Color::Red,
        Color::Orange,
    ];

    for &color in &expected_colors {
        let count = counts[color as usize];
        if count != crate::cube::STICKERS_PER_FACE {
            if count == 0 {
                return Err(CubeError::ColorNotFound(format!("{color:?}")));
            } else {
                return Err(CubeError::InvalidColors(format!(
                    "{color:?}の数が{count}個です（{}個である必要があります）",
                    crate::cube::STICKERS_PER_FACE
                )));
            }
        }
    }

    Ok(())
}

/// キューブの状態が有効かどうかを判定します。
pub fn is_valid_state(cube: &Cube) -> Result<()> {
    // まず色数のチェック
    let mut colors_array = [Color::White; crate::cube::NUM_STICKERS];
    for (i, color) in colors_array.iter_mut().enumerate() {
        *color = cube.stickers[i].color;
    }
    validate_colors(&colors_array)?;

    // コーナーのパリティと一貫性をチェック
    check_corner_parity(cube)?;

    // エッジのパリティと一貫性をチェック
    check_edge_parity(cube)?;

    // 置換パリティをチェック
    check_total_permutation_parity(cube)?;

    Ok(())
}

