    /// 3Dビューの描画処理
    fn show_3d_view(&mut self, ui: &mut egui::Ui) {
        let available = ui.available_size();
        let size = available.x.min(available.y);
        let y_offset = (available.y - size) / 2.0;

        if y_offset > 0.0 {
            ui.add_space(y_offset);
        }

        ui.horizontal(|ui| {
            let x_offset = (ui.available_width() - size) / 2.0;
            if x_offset > 0.0 {
                ui.add_space(x_offset);
            }

            // 描画領域 (正方形)
            let rect_size = egui::vec2(size, size);
            let (rect, response) = ui.allocate_at_least(rect_size, egui::Sense::drag());

            // 3Dビュー操作
            if response.dragged() {
                self.view_3d.yaw += response.drag_delta().x * MOUSE_SENSITIVITY;
                self.view_3d.pitch += response.drag_delta().y * MOUSE_SENSITIVITY;

                // Pitch制限
                self.view_3d.pitch = self.view_3d.pitch.clamp(
                    -std::f32::consts::FRAC_PI_2 + VIEW3D_PITCH_LIMIT_MARGIN,
                    std::f32::consts::FRAC_PI_2 - VIEW3D_PITCH_LIMIT_MARGIN,
                );
            }
            // ズーム操作
            let scroll_delta = ui.input(|i| i.raw_scroll_delta.y);
            if scroll_delta != 0.0 {
                self.view_3d.scale *= if scroll_delta > 0.0 {
                    ZOOM_FACTOR
                } else {
                    1.0 / ZOOM_FACTOR
                };
                self.view_3d.scale = self.view_3d.scale.clamp(ZOOM_MIN, ZOOM_MAX);
            }

            let display_cube = self.display_cube();
            let highlight_face = self.editing_face_index();
            draw_cube_3d(
                ui,
                rect,
                &display_cube,
                self.animation.as_ref(),
                &self.view_3d,
                highlight_face,
            );
        });
    }

    /// 2Dビューの描画処理
    fn show_2d_view(&mut self, ui: &mut egui::Ui) {
        let available = ui.available_size();
        let size = available.x.min(available.y);

        let (rect, _response) =
            ui.allocate_exact_size(egui::vec2(available.x, size), egui::Sense::hover());

        let display_cube = self.display_cube();
        let highlight_face = self.editing_face_index();
        crate::gui::renderer::draw_cube(
            ui,
            rect,
            &display_cube,
            self.animation.as_ref(),
            highlight_face,
        );
    }

    // ============ 6面スキャン入力モード用メソッド ============

    /// スキャンモードを開始
    pub fn start_scanning_mode(&mut self) {
        self.input_state = InputState::Scanning { face_index: 0 };
        self.input_buffer = [None; 54];
        self.selected_input_color = Color::White;
        self.input_error_message.clear();
    }

    /// スキャンモードをキャンセル
    pub fn cancel_scanning_mode(&mut self) {
        self.input_state = InputState::Normal;
        self.input_buffer = [None; 54];
        self.input_error_message.clear();
    }

    /// 次の面へ進む
    pub fn next_face(&mut self) {
        if let InputState::Scanning { face_index } = self.input_state {
            if face_index < 5 {
                self.input_state = InputState::Scanning {
                    face_index: face_index + 1,
                };
            }
        }
    }

    /// 前の面へ戻る
    pub fn prev_face(&mut self) {
        if let InputState::Scanning { face_index } = self.input_state {
            if face_index > 0 {
                self.input_state = InputState::Scanning {
                    face_index: face_index - 1,
                };
            }
        }
    }

    /// 現在の面のステッカーに色を設定
    /// position: 面内の位置 0-3 (左上、右上、左下、右下)
    pub fn set_current_face_sticker(&mut self, position: usize, color: Color) {
        if let InputState::Scanning { face_index } = self.input_state {
            let global_index = face_index * 9 + position;
            if global_index < 54 {
                self.input_buffer[global_index] = Some(color);
            }
        }
    }

    /// 現在の面の指定位置のステッカー色を取得
    pub fn get_current_face_sticker(&self, position: usize) -> Option<Color> {
        if let InputState::Scanning { face_index } = self.input_state {
            let global_index = face_index * 9 + position;
            if global_index < 54 {
                return self.input_buffer[global_index];
            }
        }
        None
    }

    /// 現在の面の名前を取得
    pub fn get_current_face_name(&self) -> &str {
        if let InputState::Scanning { face_index } = self.input_state {
            match face_index {
                0 => "Up (上面)",
                1 => "Down (下面)",
                2 => "Left (左面)",
                3 => "Right (右面)",
                4 => "Front (前面)",
                5 => "Back (背面)",
                _ => "不明",
            }
        } else {
            "不明"
        }
    }

    /// 現在の面が全て入力済みかチェック
    pub fn is_current_face_complete(&self) -> bool {
        if let InputState::Scanning { face_index } = self.input_state {
            let start = face_index * 9;
            let end = start + 9;
            return self.input_buffer[start..end].iter().all(|c| c.is_some());
        }
        false
    }

    /// スキャン完了（キューブに反映）
    pub fn finish_scanning(&mut self) {
        // 全てのステッカーが入力されているかチェック
        if self.input_buffer.iter().any(|c| c.is_none()) {
            self.input_error_message = "全ての面を入力してください".to_string();
            return;
        }

        // Option<Color>をColorに変換
        let colors: [Color; 54] = self
            .input_buffer
            .iter()
            .map(|c| c.expect("全ての色が入力されています"))
            .collect::<Vec<_>>()
            .try_into()
            .expect("配列は54要素です");

        // 妥当性チェック
        if let Err(e) = Cube::validate_colors(&colors) {
            self.input_error_message = e.to_string();
            return;
        }

        // キューブに反映
        let new_cube = match Cube::from_colors(&colors) {
            Ok(cube) => cube,
            Err(e) => {
                self.input_error_message = format!("キューブの作成に失敗: {}", e);
                return;
            }
        };

        // パリティチェック（物理的に可能な配置かチェック）
        if !self.skip_parity_check {
            if let Err(e) = new_cube.is_valid_state() {
                self.input_error_message = format!("無効なキューブ状態: {}", e);
                return;
            }
        }

        self.cube = new_cube;
        self.input_state = InputState::Normal;
        self.input_buffer = [None; 54];
        self.input_error_message.clear();

        // 向きの自動復元（即時）
        if let Err(e) = self.cube.restore_orientation_instantly() {
            self.input_error_message = format!("警告: 向きの復元に失敗しました ({})", e);
        }

        // 解法やアニメーションをクリア
        self.solution = None;
        self.solution_text.clear();
        self.animation = None;
        self.move_queue.clear();
    }

    /// キューブの状態をファイルに保存
    pub fn save_to_file(&self, path: &str) -> Result<(), String> {
        // 現在表示されているキューブ（スキャン中なら入力バッファベース）を保存
        let content = self.display_cube().to_file_format();
        std::fs::write(path, content).map_err(|e| format!("ファイルの保存に失敗しました: {}", e))
    }

    /// ファイルからキューブの状態を読み込み
    pub fn load_from_file(&mut self, path: &str) -> Result<String, String> {
        let content = std::fs::read_to_string(path)
            .map_err(|e| format!("ファイルの読み込みに失敗しました: {}", e))?;

        self.load_from_content(&content)
    }

    /// 文字列（ファイル内容）からキューブの状態を読み込み
    pub fn load_from_content(&mut self, content: &str) -> Result<String, String> {
        let loaded_cube = Cube::from_file_format(content).map_err(|e| e.to_string())?;

        let mut warning = String::new();

        // 読み込んだキューブに Gray (未設定) が含まれているかチェック
        let has_gray = loaded_cube.stickers.iter().any(|s| s.color == Color::Gray);

        if has_gray {
            // スキャンモードとして復元
            self.input_state = InputState::Scanning { face_index: 0 };
            for (i, sticker) in loaded_cube.stickers.iter().enumerate() {
                self.input_buffer[i] = if sticker.color == Color::Gray {
                    None
                } else {
                    Some(sticker.color)
                };
            }
            self.cube = Cube::new(); // 内部状態はリセット
            warning = "スキャン途中の状態を読み込みました".to_string();
        } else {
            // 通常のキューブとして復元
            let mut new_cube = loaded_cube;

            // 全ての向きが0（旧形式またはリセット直後）の場合のみ、向きの自動復元を試みる
            let all_zero_orientation = new_cube.stickers.iter().all(|s| s.orientation == 0);
            if all_zero_orientation {
                if let Err(e) = new_cube.restore_orientation_instantly() {
                    warning = format!("警告: 向きの復元に失敗しました ({})", e);
                }
            }

            // パリティチェック（skip_parity_checkフラグで制御）
            if !self.skip_parity_check {
                if let Err(e) = new_cube.is_valid_state() {
                    let parity_warning = format!("警告: 無効なキューブ状態です ({})", e);
                    warning = if warning.is_empty() {
                        parity_warning
                    } else {
                        format!("{}\n{}", warning, parity_warning)
                    };
                }
            }

            self.cube = new_cube;
            self.input_state = InputState::Normal;
            self.input_buffer = [None; 54];
        }

        self.solution = None;
        self.solution_text.clear();
        self.animation = None;
        self.move_queue.clear();
        self.input_error_message.clear();

        Ok(warning)
    }

    /// 保存ダイアログを表示して保存
    #[cfg(not(target_arch = "wasm32"))]
    pub fn save_with_dialog(&mut self) {
        let task = rfd::FileDialog::new()
            .set_directory(".")
            .add_filter("Text files", &["txt"])
            .set_file_name("cube_state.txt")
            .save_file();

        if let Some(path) = task {
            let path_str = path.to_string_lossy();
            match self.save_to_file(&path_str) {
                Ok(_) => {
                    self.input_error_message = format!(
                        "保存しました: {}",
                        path.file_name().unwrap_or_default().to_string_lossy()
                    );
                }
                Err(e) => {
                    self.input_error_message = format!("保存エラー: {}", e);
                }
            }
        }
    }

    /// Web版: ブラウザのダウンロード機能でファイルを保存
    #[cfg(target_arch = "wasm32")]
    pub fn save_with_dialog(&mut self) {
        use wasm_bindgen::JsCast;
        use web_sys::{Blob, HtmlAnchorElement, Url};

        let content = self.display_cube().to_file_format();
        let array = js_sys::Uint8Array::from(content.as_bytes());
        let blob_parts = js_sys::Array::new();
        blob_parts.push(&array);

        let options = web_sys::BlobPropertyBag::new();
        options.set_type("text/plain");

        match Blob::new_with_u8_array_sequence_and_options(&blob_parts, &options) {
            Ok(blob) => match Url::create_object_url_with_blob(&blob) {
                Ok(url) => {
                    let window = web_sys::window().expect("windowオブジェクト取得失敗");
                    let document = window.document().expect("documentオブジェクト取得失敗");

                    if let Ok(element) = document.create_element("a") {
                        let anchor: HtmlAnchorElement =
                            element.dyn_into().expect("a要素へのキャスト失敗");
                        anchor.set_href(&url);
                        anchor.set_download("cube_state.txt");
                        anchor.click();

                        let _ = Url::revoke_object_url(&url);
                        self.input_error_message =
                            "ダウンロードを開始しました: cube_state.txt".to_string();
                    } else {
                        self.input_error_message = "保存エラー: a要素の作成に失敗".to_string();
                    }
                }
                Err(_) => {
                    self.input_error_message = "保存エラー: URLの生成に失敗".to_string();
                }
            },
            Err(_) => {
                self.input_error_message = "保存エラー: Blobの作成に失敗".to_string();
            }
        }
    }

    /// 読込ダイアログを表示して読み込み
    #[cfg(not(target_arch = "wasm32"))]
    pub fn load_with_dialog(&mut self) {
        let task = rfd::FileDialog::new()
            .set_directory(".")
            .add_filter("Text files", &["txt"])
            .pick_file();

        if let Some(path) = task {
            let path_str = path.to_string_lossy();
            match self.load_from_file(&path_str) {
                Ok(warning) => {
                    if warning.is_empty() {
                        self.input_error_message = format!(
                            "読み込みました: {}",
                            path.file_name().unwrap_or_default().to_string_lossy()
                        );
                    } else {
                        self.input_error_message = format!("読み込み完了: {}", warning);
                    }
                }
                Err(e) => {
                    self.input_error_message = format!("読み込みエラー: {}", e);
                }
            }
        }
    }

    /// Web版: ブラウザのファイル選択機能でファイルを読み込み
    #[cfg(target_arch = "wasm32")]
    pub fn load_with_dialog(&mut self) {
        let (tx, rx) = std::sync::mpsc::channel();
        self.file_receiver = Some(rx);

        // WASM環境では、AsyncFileDialogを使用して非同期にファイルを選択
        wasm_bindgen_futures::spawn_local(async move {
            let task = rfd::AsyncFileDialog::new()
                .add_filter("Text files", &["txt"])
                .pick_file();

            if let Some(file_handle) = task.await {
                let bytes = file_handle.read().await;
                let content = String::from_utf8_lossy(&bytes).to_string();
                let _ = tx.send(Ok(content));
            }
        });
    }

    /// キーボード入力を処理
    fn handle_input(&mut self, ctx: &egui::Context) {
        // アニメーション中やソルブ中は入力を受け付けない（オプション）
        // ここでは連打できるように許可するが、キューに追加される

        // Shiftキーが押されているか確認
        let shift = ctx.input(|i| i.modifiers.shift);

        // 各キーの処理
        let input = ctx.input(|i| {
            let mut moves = Vec::new();

            if i.key_pressed(egui::Key::R) {
                moves.push(if shift { Move::Rp } else { Move::R });
            }
            if i.key_pressed(egui::Key::L) {
                moves.push(if shift { Move::Lp } else { Move::L });
            }
            if i.key_pressed(egui::Key::U) {
                moves.push(if shift { Move::Up } else { Move::U });
            }
            if i.key_pressed(egui::Key::D) {
                moves.push(if shift { Move::Dp } else { Move::D });
            }
            if i.key_pressed(egui::Key::F) {
                moves.push(if shift { Move::Fp } else { Move::F });
            }
            if i.key_pressed(egui::Key::B) {
                moves.push(if shift { Move::Bp } else { Move::B });
            }
            moves
        });

        for mv in input {
            self.queue_move(mv);
        }

        // 機能キー
        if ctx.input(|i| i.key_pressed(egui::Key::S)) {
            self.scramble();
        }
        if ctx.input(|i| i.key_pressed(egui::Key::Space)) && !self.solving {
            self.solve();
        }
        if ctx.input(|i| i.key_pressed(egui::Key::Escape)) {
            self.reset();
        }
    }

    /// アプリケーションのコアロジックを更新します（UIレンダリング以外）
    pub fn update_logic(&mut self, ctx: &egui::Context) {
        // WASM環境: ペンディング状態のソルバーを起動
        #[cfg(target_arch = "wasm32")]
        if let Some((_task, ignore_orientation, mut frames_to_wait)) =
            self.pending_solver_start.take()
        {
            if frames_to_wait > 0 {
                // まだ待機中：カウンターをデクリメントして再設定
                frames_to_wait -= 1;
                self.pending_solver_start = Some((_task, ignore_orientation, frames_to_wait));
            } else {
                // 待機完了：インクリメンタルソルバーを初期化
                let max_depth = solver::DEFAULT_MAX_DEPTH;
                self.solver_state = Some(solver::SolverState::new(
                    &self.cube,
                    max_depth,
                    ignore_orientation,
                ));
            }
        }

        // WASM環境: インクリメンタルソルバーのチャンク処理
        #[cfg(target_arch = "wasm32")]
        if let Some(state) = &mut self.solver_state {
            // 100ノード処理（約10-20ms）
            let (_processed, is_complete) = state.process_chunk(100);

            if is_complete {
                // 完了: 結果を取得
                if let Some(solution) = state.get_solution() {
                    if solution.found {
                        self.solution = Some(solution.moves.clone());
                        let duration_text = if let Some(d) = self.last_solve_duration {
                            format!(" ({:.2}秒)", d)
                        } else if let Some(start_time) = self.solving_start_time {
                            let duration = start_time.elapsed().as_secs_f32();
                            self.last_solve_duration = Some(duration);
                            format!(" ({:.2}秒)", duration)
                        } else {
                            String::new()
                        };
                        self.solution_text =
                            format!("解法: {} 手{}", solution.moves.len(), duration_text);
                        self.solution_step = 0;
                    } else {
                        self.solution = None;
                        self.solution_text = "解が見つかりませんでした".to_string();
                    }
                }

                self.solving = false;
                self.solver_state = None;
            } else {
                // 進捗更新
                self.solver_progress = state.estimate_progress();
            }
        }

        self.check_solver_result();
        self.check_progress();
        self.update_animation();
        self.handle_input(ctx);

        // ファイル読み込みの結果を確認
        if let Some(rx) = &self.file_receiver {
            if let Ok(result) = rx.try_recv() {
                self.file_receiver = None;
                match result {
                    Ok(content) => match self.load_from_content(&content) {
                        Ok(warning) => {
                            if warning.is_empty() {
                                self.input_error_message = "ファイルを読み込みました".to_string();
                            } else {
                                self.input_error_message = format!("読み込み完了: {}", warning);
                            }
                        }
                        Err(e) => {
                            self.input_error_message = format!("読み込みエラー: {}", e);
                        }
                    },
                    Err(e) => {
                        self.input_error_message = format!("ファイル選択エラー: {}", e);
                    }
                }
            }
        }

        // 継続的な再描画をリクエスト
        ctx.request_repaint();
    }
}

impl eframe::App for CubeApp {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.update_logic(ctx);

        // 右側のサイドパネル (コントロールパネル)
        egui::SidePanel::right("control_panel")
            .min_width(UI_SIDE_PANEL_WIDTH)
            .default_width(UI_SIDE_PANEL_WIDTH)
            .resizable(false)
            .show(ctx, |ui| {
                egui::ScrollArea::vertical()
                    .id_salt("side_panel_scroll")
                    .show(ui, |ui| {
                        ui.vertical(|ui| {
                            ui.add_space(UI_SPACING_LARGE);
                            crate::gui::controls::draw_controls(self, ui);
                        });
                    });
            });

        // 中央パネル (メインコンテンツ)
        egui::CentralPanel::default().show(ctx, |ui| {
            ui.horizontal(|ui| {
                ui.heading("3x3 ルービックキューブ");
                ui.add_space(20.0);
                ui.hyperlink_to("⬅ 2x2版はこちら", "../");

                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    ui.selectable_value(&mut self.view_mode, ViewMode::Both, "2D & 3D");
                    ui.selectable_value(&mut self.view_mode, ViewMode::ThreeD, "3Dのみ");
                    ui.selectable_value(&mut self.view_mode, ViewMode::TwoD, "2Dのみ");
                });
            });
            ui.add_space(UI_SPACING_LARGE);

            // キューブ表示領域
            ui.group(|ui| {
                // 利用可能なサイズを計算
                ui.set_min_width(300.0);
                ui.set_min_height(300.0);

                match self.view_mode {
                    ViewMode::TwoD => {
                        self.show_2d_view(ui);
                    }
                    ViewMode::ThreeD => {
                        ui.vertical(|ui| {
                            ui.heading("3Dビュー");
                            ui.label(
                                egui::RichText::new("ドラッグで回転、ホイールでズーム")
                                    .size(UI_HELP_TEXT_SIZE),
                            );
                            self.show_3d_view(ui);
                        });
                    }
                    ViewMode::Both => {
                        ui.columns(2, |columns| {
                            columns[0].vertical(|ui| {
                                ui.heading("3Dビュー");
                                ui.label(
                                    egui::RichText::new("ドラッグで回転、ホイールでズーム")
                                        .size(UI_HELP_TEXT_SIZE),
                                );
                                self.show_3d_view(ui);
                            });
                            columns[1].vertical(|ui| {
                                ui.heading("展開図");
                                self.show_2d_view(ui);
                            });
                        });
                    }
                }
            });
        });
    }
}

