        }
    });

    ui.add_space(UI_SPACING_LARGE);

    // ファイル保存・読み込み
    ui.label("ファイル:");
    ui.horizontal(|ui| {
        if ui.button("💾 保存").clicked() {
            app.save_with_dialog();
        }
        if ui.button("📂 読み込み").clicked() {
            app.load_with_dialog();
        }
    });

    ui.add_space(UI_SPACING_LARGE);

    // Undo/Redo
    ui.horizontal(|ui| {
        if ui
            .add_enabled(app.history.can_undo(), egui::Button::new("↶ Undo"))
            .clicked()
