use crate::cube::{Color, Cube, Face, Move, Sticker, STICKERS_PER_FACE};
use crate::gui::app::AnimationState;
use crate::gui::constants::*;
use egui::{Color32, Painter, Pos2, Rect, Stroke, Vec2};

/// キューブのステッカー色（[`Color`]）を egui の [`Color32`] に変換します。
///
/// # 引数
///
/// - `color` - 変換元のステッカー色
///
/// # 戻り値
///
/// egui で描画可能な Color32 値
#[must_use]
pub fn color_to_color32(color: Color) -> Color32 {
    match color {
        Color::White => COLOR_WHITE,
        Color::Yellow => COLOR_YELLOW,
        Color::Green => COLOR_GREEN,
        Color::Blue => COLOR_BLUE,
        Color::Red => COLOR_RED,
        Color::Orange => COLOR_ORANGE,
        Color::Gray => COLOR_GRAY,
    }
}

/// 単一のステッカーを描画します。
///
/// 指定された回転角度や透明度を適用して、正方形のステッカーとその上の向きを示す矢印を描画します。
fn draw_sticker(
    painter: &Painter,
    center: Pos2,
    size: f32,
    sticker: Sticker,
    rotation_offset_deg: f32,
    alpha: f32,
    shadow_offset: Vec2,
) {
    let color = color_to_color32(sticker.color).linear_multiply(alpha);
    let stroke_color = Color32::BLACK.linear_multiply(alpha);

    // 影の描画 (もしあれば)
    if shadow_offset.length() > 0.1 {
        let shadow_color = Color32::from_black_alpha((100.0 * alpha) as u8);
        let shadow_rect = Rect::from_center_size(
            center + shadow_offset,
            Vec2::splat(size * STICKER_SIZE_RATIO),
        );
        painter.rect_filled(shadow_rect, STICKER_ROUNDING, shadow_color);
    }

    // ステッカーの背景を描画
    let rect = Rect::from_center_size(center, Vec2::splat(size * STICKER_SIZE_RATIO));

    // 回転を適用した矩形を描画するために、頂点を計算して回転させる
    if rotation_offset_deg.abs() > 0.1 {
        let angle = rotation_offset_deg.to_radians();
        let cos = angle.cos();
        let sin = angle.sin();

        let half = size * STICKER_SIZE_RATIO / 2.0;
        let corners = [
            Pos2::new(-half, -half),
            Pos2::new(half, -half),
            Pos2::new(half, half),
            Pos2::new(-half, half),
        ];

        let rotated_corners: Vec<Pos2> = corners
            .iter()
            .map(|p| {
                Pos2::new(
                    center.x + p.x * cos - p.y * sin,
                    center.y + p.x * sin + p.y * cos,
                )
            })
            .collect();

        painter.add(egui::Shape::convex_polygon(
            rotated_corners.clone(),
            color,
            Stroke::new(STICKER_STROKE_WIDTH, stroke_color),
        ));
    } else {
        painter.rect_filled(rect, STICKER_ROUNDING, color);
        painter.rect_stroke(
            rect,
            STICKER_ROUNDING,
            Stroke::new(STICKER_STROKE_WIDTH, stroke_color),
        );
    }

    // 矢印を描画（向きを示す）
    let arrow_rotation = (sticker.orientation as f32 * 90.0 + rotation_offset_deg).to_radians();
    draw_arrow(
        painter,
        center,
        size * ARROW_LENGTH_RATIO,
        arrow_rotation,
        alpha,
    );
}

/// ステッカーの向き（orientation）を示す矢印を描画します。
fn draw_arrow(painter: &Painter, center: Pos2, length: f32, rotation: f32, alpha: f32) {
    let cos = rotation.cos();
    let sin = rotation.sin();

    // 矢印の先端
    let tip = Pos2::new(center.x + length * sin, center.y - length * cos);

    // 矢印の根元
    let base = Pos2::new(
        center.x - length * ARROW_BASE_RATIO * sin,
        center.y + length * ARROW_BASE_RATIO * cos,
    );

    // 矢印の羽
    let wing_length = length * ARROW_WING_RATIO;
    let wing_angle = ARROW_WING_ANGLE_DEG.to_radians();

    let left_wing = Pos2::new(
        tip.x - wing_length * (rotation + wing_angle).sin(),
        tip.y + wing_length * (rotation + wing_angle).cos(),
    );

    let right_wing = Pos2::new(
        tip.x - wing_length * (rotation - wing_angle).sin(),
        tip.y + wing_length * (rotation - wing_angle).cos(),
    );

    // 矢印を描画
    // Color32::from_black_alpha(180) は alpha=180/255 相当。
    // alpha引数を反映させるため、Color32::BLACK.linear_multiply(alpha)をベースに調整してもいいが、
    // ここでは単純に linear_multiply を使う
    let stroke = Stroke::new(
        ARROW_WIDTH,
        Color32::from_black_alpha(ARROW_ALPHA).linear_multiply(alpha),
    );
    painter.line_segment([base, tip], stroke);
    painter.line_segment([tip, left_wing], stroke);
    painter.line_segment([tip, right_wing], stroke);
}

/// インデックスに対応するグリッド座標 (col, row) を取得
fn get_grid_coords(index: usize) -> Pos2 {
    let (col, row) = match index {
        i if i < 9 => (3.0 + (i % 3) as f32, 0.0 + (i / 3) as f32), // U
        i if i < 18 => (3.0 + ((i - 9) % 3) as f32, 6.0 + ((i - 9) / 3) as f32), // D
        i if i < 27 => (0.0 + ((i - 18) % 3) as f32, 3.0 + ((i - 18) / 3) as f32), // L
        i if i < 36 => (6.0 + ((i - 27) % 3) as f32, 3.0 + ((i - 27) / 3) as f32), // R
        i if i < 45 => (3.0 + ((i - 36) % 3) as f32, 3.0 + ((i - 36) / 3) as f32), // F
        _ => (
            9.0 + ((index - 45) % 3) as f32,
            3.0 + ((index - 45) / 3) as f32,
        ), // B
    };
    Pos2::new(col, row)
}

/// アニメーション情報の型エイリアス: (移動マッピング, 回転面情報)
type AnimationInfo = (Vec<(usize, usize)>, Option<(usize, f32)>);

/// アニメーション情報：移動マッピングと回転面情報
fn get_animation_info(mv: Move) -> AnimationInfo {
    let all_moves = Move::all_moves();
    let move_idx = all_moves.iter().position(|&m| m == mv).unwrap_or(0);

    let mut mapping = Vec::new();
    let (face_start, _) = crate::gui::mapping::FACE_ROTATION_TABLE[move_idx];

    for &(src, dst) in &crate::gui::mapping::MOVE_MAPPING_TABLE[move_idx] {
        if src == 99 {
            continue;
        }

        // 移動があるステッカー、または回転面上のステッカーのみを対象にする
        let is_on_face = if face_start != usize::MAX {
            src >= face_start && src < face_start + STICKERS_PER_FACE
        } else {
            false
        };

        if src != dst || is_on_face {
            mapping.push((src, dst));
        }
    }

    (
        mapping,
        Some(crate::gui::mapping::FACE_ROTATION_TABLE[move_idx]),
    )
}

/// キューブを展開図（2D）として指定された領域に描画します。
///
/// 現在のアニメーション状態（[`AnimationState`]）がある場合は、
/// 回転や移動の演出を適用して描画します。
///
/// # 引数
///
/// - `ui` - egui の Ui コンテキスト
/// - `rect` - 描画先の矩形領域
/// - `cube` - 描画対象のキューブ
/// - `animation` - 現在実行中のアニメーション状態（任意）
/// - `highlight_face_index` - ハイライト表示する面のインデックス（任意、0-5）
pub fn draw_cube(
    ui: &mut egui::Ui,
    mut rect: Rect,
    cube: &Cube,
    animation: Option<&AnimationState>,
    highlight_face_index: Option<usize>,
) {
    if !rect.is_finite() {
        rect = ui.available_rect_before_wrap();
    }
    let painter = ui.painter();

    let grid_cols = GRID_COLS;
    let grid_rows = GRID_ROWS;

    // グリッドサイズ計算
    let mut grid_size =
        (rect.width() / grid_cols).min(rect.height() / grid_rows) * GRID_PADDING_RATIO;
    if grid_size.is_nan() || grid_size < 0.1 {
        grid_size = 1.0;
    }
    let sticker_size = grid_size * STICKER_SIZE_IN_GRID;

    let total_width = grid_size * grid_cols;
    let total_height = grid_size * grid_rows;

    let start_x = rect.left() + (rect.width() - total_width) / 2.0;
    let start_y = rect.top() + (rect.height() - total_height) / 2.0;
    let base_pos = Pos2::new(start_x + grid_size * 0.5, start_y + grid_size * 0.5);

    let to_screen = |grid_p: Pos2| -> Pos2 {
        Pos2::new(
            base_pos.x + grid_p.x * grid_size,
            base_pos.y + grid_p.y * grid_size,
        )
    };

    let (anim_mapping, anim_face_rot) = if let Some(anim) = animation {
        get_animation_info(anim.current_move)
    } else {
        (vec![], None)
    };

    // 0. 回転面の強調表示 (Face Overlay)
    if let Some((face_start, _angle)) = anim_face_rot {
        if face_start != usize::MAX {
            let face_grid_rect = get_face_grid_rect(face_start);
            let top_left = to_screen(face_grid_rect.min) - Vec2::splat(grid_size * 0.5);
            let bottom_right = to_screen(Pos2::new(
                face_grid_rect.max.x - 1.0,
                face_grid_rect.max.y - 1.0,
            )) + Vec2::splat(grid_size * 0.5);
            let highlight_rect = Rect::from_min_max(top_left, bottom_right);

            painter.rect_filled(
                highlight_rect.expand(2.0),
                5.0,
                Color32::from_rgba_premultiplied(128, 128, 128, ANIMATION_FACE_HIGHLIGHT_ALPHA),
            );
        }
    }

    // 全ステッカーを描画
    for i in 0..crate::cube::NUM_STICKERS {
        let grid_pos = get_grid_coords(i);
        let screen_pos = to_screen(grid_pos);
        let mut drawn = false;

        let mut sticker = cube.get_sticker(i);

        if let Some(anim) = animation {
            let progress = anim.eased_progress();

            // 描画対象を決定: 移動中のスロットであればソースからステッカーを取得
            if let Some(&(src, _)) = anim_mapping.iter().find(|(_, dst)| *dst == i) {
                let moving_from_idx = src;
                let oris_delta =
                    crate::gui::mapping::get_oris_delta(anim.current_move, moving_from_idx);

                // Piece ベースに移行したため、現在の位置 (i) にあるステッカーを取得します。
                // アニメーションの開始時 (t=0) の向きを再現するため、oris_delta 分だけ戻した値を src_ori とします。
                sticker = cube.get_sticker(i);
                let src_ori = (sticker.orientation as i32 + 4 - (oris_delta % 4) as i32) as u8 % 4;

                let target_grid_pos = grid_pos; //目的地
                let start_grid_pos = get_grid_coords(src); //出発地
                let dist = start_grid_pos.distance(target_grid_pos);

                let start_screen = to_screen(start_grid_pos);
                let end_screen = to_screen(target_grid_pos);

                let (is_arc, rotation_face_start) = match anim.current_move {
                    Move::U | Move::Up | Move::U2 => (matches!(i, 0..=8), 0),
                    Move::D | Move::Dp | Move::D2 => (matches!(i, 9..=17), 9),
                    Move::L | Move::Lp | Move::L2 => (matches!(i, 18..=26), 18),
                    Move::R | Move::Rp | Move::R2 => (matches!(i, 27..=35), 27),
                    Move::F | Move::Fp | Move::F2 => (
                        matches!(i, 36..=44 | 6..=8 | 27 | 30 | 33 | 9..=11 | 20 | 23 | 26),
                        36,
                    ),
                    Move::B | Move::Bp | Move::B2 => (matches!(i, 45..=53), 45),
                    Move::S | Move::Sp | Move::S2 => (
                        matches!(i, 3..=5 | 28 | 31 | 34 | 12..=14 | 19 | 22 | 25),
                        36,
                    ),
                    _ => (false, 0),
                };

                // アニメーション中のステッカーの論理的向きは、開始時の状態に固定して描画する
                // (実際の回転は sub_rot や p_rot で表現される)
                sticker.orientation = src_ori;

                let calc_state = |p: f32| {
                    let mut pos = start_screen + (end_screen - start_screen) * p;
                    let mut rot = 0.0;
                    let mut alpha = 1.0;
                    let mut size_scale = 1.0;
                    let mut shadow = Vec2::ZERO;

                    if is_arc {
                        if let Some((_, angle)) = anim_face_rot {
                            let center_grid_base = get_face_grid_rect(rotation_face_start).min;
                            let center_grid =
                                Pos2::new(center_grid_base.x + 1.0, center_grid_base.y + 1.0);
                            let center_screen = to_screen(center_grid);

                            let r = start_screen.distance(center_screen);
                            let start_angle = (start_screen.y - center_screen.y)
                                .atan2(start_screen.x - center_screen.x);
                            let current_angle = start_angle + (angle * p).to_radians();

                            pos = Pos2::new(
                                center_screen.x + current_angle.cos() * r,
                                center_screen.y + current_angle.sin() * r,
                            );
                            rot = angle * p;
                        }
                    } else {
                        // 直線移動 (Slide) の場合
                        let mid_p = (p * std::f32::consts::PI).sin();
                        let is_slice = matches!(
                            anim.current_move,
                            Move::M
                                | Move::Mp
                                | Move::M2
                                | Move::E
                                | Move::Ep
                                | Move::E2
                                | Move::S
                                | Move::Sp
                                | Move::S2
                        );

                        if dist >= 3.0 && !is_slice {
                            let bulge_val = ANIMATION_JUMP_BULGE_RATIO * grid_size;
                            pos.y -= bulge_val * mid_p;
                            alpha = 1.0 - 0.5 * mid_p;
                            size_scale = 1.0 - 0.3 * mid_p;
                            shadow = Vec2::new(
                                ANIMATION_JUMP_SHADOW_OFFSET,
                                ANIMATION_JUMP_SHADOW_OFFSET,
                            ) * mid_p;
                        } else if !is_slice {
                            pos.y += ANIMATION_BULGE_RATIO * grid_size * mid_p;
                            shadow =
                                Vec2::new(ANIMATION_SHADOW_OFFSET, ANIMATION_SHADOW_OFFSET) * mid_p;
                        }
                    }
                    (pos, rot, size_scale, alpha, shadow)
                };

                let (p_pos, p_rot, p_scale, p_alpha, p_shadow) = calc_state(progress);

                let move_angle = if is_arc {
                    if let Some((_, angle)) = anim_face_rot {
                        angle
                    } else {
                        0.0
                    }
                } else {
                    0.0
                };

                // 目標とする自転量 (oris_delta * 90) から、アニメーションによる回転分 (move_angle) を引いた残りを補完
                let target_sub_rot = (oris_delta as f32 * 90.0 - move_angle).rem_euclid(360.0);
                let target_sub_rot = if target_sub_rot > 180.0 {
                    target_sub_rot - 360.0
                } else {
                    target_sub_rot
                };
                let sub_rot = target_sub_rot * progress;

                for ghost_t in [0.05, 0.1] {
                    let t = (progress - ghost_t).max(0.0);
                    if t > 0.0 {
                        let (g_pos, g_rot, g_scale, g_alpha, _) = calc_state(t);
                        draw_sticker(
                            painter,
                            g_pos,
                            sticker_size * g_scale * (1.0 - ghost_t * 2.0),
                            sticker,
                            g_rot + sub_rot,
                            ANIMATION_TRAIL_ALPHA_FACTOR
                                * g_alpha
                                * p_alpha
                                * (1.0 - ghost_t * 5.0),
                            Vec2::ZERO,
                        );
                    }
                }

                draw_sticker(
                    painter,
                    p_pos,
                    sticker_size * p_scale,
                    sticker,
                    p_rot + sub_rot,
                    p_alpha,
                    p_shadow,
                );
                drawn = true;
            } else if anim_mapping.iter().any(|(src_m, _)| *src_m == i) {
                drawn = true;
            }
        }

        if !drawn {
            draw_sticker(
                painter,
                screen_pos,
                sticker_size,
                sticker,
                0.0, // 基準向きを 0.0 (UP) に統一
                1.0,
                Vec2::ZERO,
            );
        }
    }

    // ハイライト
    if let Some(face_idx) = highlight_face_index {
        let face_grid_rect = get_face_grid_rect(face_idx * STICKERS_PER_FACE);
        let top_left = to_screen(face_grid_rect.min) - Vec2::splat(grid_size * 0.5);
        let bottom_right = to_screen(Pos2::new(
            face_grid_rect.max.x - 1.0,
            face_grid_rect.max.y - 1.0,
        )) + Vec2::splat(grid_size * 0.5);
        let padding = grid_size * HIGHLIGHT_PADDING_RATIO;
        let highlight_rect = Rect::from_min_max(
            top_left - Vec2::splat(padding),
            bottom_right + Vec2::splat(padding),
        );
        painter.rect_stroke(
            highlight_rect,
            5.0,
            Stroke::new(HIGHLIGHT_STROKE_WIDTH, HIGHLIGHT_COLOR),
        );
    }

    if let Some(anim) = animation {
        let text = format!(
            "動作: {} ({:.0}%)",
            anim.current_move,
            anim.progress * 100.0
        );
        painter.text(
            rect.left_bottom() + egui::vec2(10.0, -30.0),
            egui::Align2::LEFT_BOTTOM,
            text,
            egui::FontId::proportional(16.0),
            Color32::BLACK,
        );
    }
}

/// 移動するステッカーの向きの変更量を取得
///
fn get_face_grid_rect(index: usize) -> Rect {
    let (min_col, min_row) = match index {
        i if i == Face::Up.start_index() => (3.0, 0.0),   // U
        i if i == Face::Down.start_index() => (3.0, 6.0), // D
        i if i == Face::Left.start_index() => (0.0, 3.0), // L
        i if i == Face::Right.start_index() => (6.0, 3.0), // R
        i if i == Face::Front.start_index() => (3.0, 3.0), // F
        i if i == Face::Back.start_index() => (9.0, 3.0), // B
        _ => (0.0, 0.0),
    };
    // 3x3なのでサイズは3.0x3.0
    Rect::from_min_size(Pos2::new(min_col, min_row), Vec2::new(3.0, 3.0))
}

use crate::cube::{piece::face_to_local_index, Cube, Face, Move};
use crate::gui::app::AnimationState;
use crate::gui::constants::*;
use egui::{Color32, Pos2, Rect, Stroke};
use glam::{Mat4, Vec3};

/// 3D描画の設定
pub struct View3D {
    pub yaw: f32,
    pub pitch: f32,
    pub scale: f32,
}

impl Default for View3D {
    fn default() -> Self {
        Self {
            yaw: VIEW3D_DEFAULT_YAW,
            pitch: VIEW3D_DEFAULT_PITCH,
            scale: VIEW3D_DEFAULT_SCALE,
        }
    }
}

/// 描画用の頂点データ
struct DrawFace {
    z_score: f32,
    points: Vec<Pos2>,
    color: Color32,
    sticker_index: usize,
    center_2d: Pos2,
    arrow_end_2d: Pos2,
}

/// 3D投影ヘルパー関数
fn project_point(p: Vec3, view_mat: &Mat4, scale: f32, screen_center: Pos2) -> Pos2 {
    let view = view_mat.transform_point3(p);
    let distance = VIEW3D_CAMERA_DISTANCE - view.z;
    let perspective = VIEW3D_CAMERA_DISTANCE / distance;
    Pos2::new(
        screen_center.x + view.x * scale * perspective,
        screen_center.y - view.y * scale * perspective,
    )
}

/// 3D空間で矢印を描画
fn draw_arrow_3d(painter: &egui::Painter, center: Pos2, target: Pos2, color: Color32, width: f32) {
    let direction = target - center;
    let arrow_length = direction.length();
    if arrow_length < 0.1 {
        return;
    }

    let dir_normalized = direction.normalized();
    let arrow_end = center + dir_normalized * arrow_length;

    painter.line_segment([center, arrow_end], Stroke::new(width, color));

    let arrow_head_size = arrow_length * VIEW3D_ARROW_HEAD_RATIO;
    let perpendicular = egui::vec2(-dir_normalized.y, dir_normalized.x);

    let tip = arrow_end;
    let left = arrow_end - dir_normalized * arrow_head_size + perpendicular * arrow_head_size * 0.5;
    let right =
        arrow_end - dir_normalized * arrow_head_size - perpendicular * arrow_head_size * 0.5;

    painter.add(egui::Shape::convex_polygon(
        vec![tip, left, right],
        color,
        Stroke::NONE,
    ));
}

/// 3D描画関数
pub fn draw_cube_3d(
    ui: &mut egui::Ui,
    rect: Rect,
    cube: &Cube,
    animation: Option<&AnimationState>,
    view: &View3D,
    highlight_face_index: Option<usize>,
) {
    let painter = ui.painter();

    // カメラ設定
    let center = rect.center();
    let min_dim = rect.width().min(rect.height());
    let scale = min_dim * VIEW3D_PROJECTION_SCALE * view.scale;

    // ビュー行列 (Orbit camera)
    let view_mat = Mat4::from_rotation_x(view.pitch) * Mat4::from_rotation_y(view.yaw);

    // アニメーション情報
    let (anim_axis, anim_layer, anim_full_angle) = if let Some(anim) = animation {
        move_to_anim_params(anim.current_move)
    } else {
        (Vec3::X, 0, 0.0)
    };

    let anim_angle = if let Some(anim) = animation {
        anim_full_angle * (anim.eased_progress() - 1.0)
    } else {
        0.0
    };

    let mut draw_faces = Vec::new();
    let size = VIEW3D_STICKER_SIZE;

    for piece in &cube.pieces {
        // アニメーションによる追加回転
        let mut anim_mat = Mat4::IDENTITY;
        if let Some(_anim) = animation {
            if is_affected(piece.current_pos, anim_axis, anim_layer) {
                anim_mat = Mat4::from_axis_angle(anim_axis, anim_angle);
            }
        }

        let total_piece_rot = anim_mat * piece.current_rot;
        // Pieceの現在地（浮動小数点数）
        let current_pos_3d = anim_mat.transform_point3(piece.current_pos);

        for sticker in &piece.stickers {
            let initial_normal = sticker.initial_normal;
            let current_normal = total_piece_rot.transform_vector3(initial_normal);
            let world_normal = view_mat.transform_vector3(current_normal);

            // バックフェイスカリング
            if world_normal.z > VIEW3D_BACKFACE_CULLING_THRESHOLD {
                // 頂点の計算
                // ステッカーのローカル座標系での u, v ベクトル
                let (u_axis, v_axis) = get_sticker_axes(initial_normal);
                let u_vec = total_piece_rot.transform_vector3(u_axis) * size;
                let v_vec = total_piece_rot.transform_vector3(v_axis) * size;
                let sticker_center = current_pos_3d + current_normal * 0.5; // ピースの表面

                let corners = [
                    sticker_center - u_vec - v_vec,
                    sticker_center + u_vec - v_vec,
                    sticker_center + u_vec + v_vec,
                    sticker_center - u_vec + v_vec,
                ];

                let mut transformed_corners = Vec::with_capacity(4);
                let mut avg_z = 0.0;
                for &p in &corners {
                    let p_view = view_mat.transform_point3(p);
                    transformed_corners.push(project_point(p, &view_mat, scale, center));
                    avg_z += p_view.z;
                }
                avg_z /= 4.0;

                // ステッカーのインデックスを特定（ハイライト用）
                let face = normal_to_face(current_normal);
                let local_idx = face_to_local_index(face, piece.current_pos); // ここはオリジナルの位置で判定
                let abs_idx = face.start_index() + local_idx;

                // 矢印の向きを計算 (Piece の回転そのものを使用)
                // v_vec は Piece の初期 Up 方向 (v_axis) を現在の Piece 回転で回したもの。
                // これが物理的な矢印の向きそのものであるため、orientation による追加回転は不要。
                let arrow_dir = v_vec;

                let arrow_base_3d = sticker_center - arrow_dir * (VIEW3D_ARROW_VEC_SCALE * 0.3);
                let arrow_end_3d = sticker_center + arrow_dir * (VIEW3D_ARROW_VEC_SCALE * 0.7);

                draw_faces.push(DrawFace {
                    z_score: avg_z,
                    points: transformed_corners,
                    color: crate::gui::renderer::color_to_color32(sticker.color),
                    sticker_index: abs_idx,
                    center_2d: project_point(arrow_base_3d, &view_mat, scale, center),
                    arrow_end_2d: project_point(arrow_end_3d, &view_mat, scale, center),
                });
            }
        }
    }

    // Zソート
    draw_faces.sort_by(|a, b| {
        a.z_score
            .partial_cmp(&b.z_score)
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    // 描画
    for face in draw_faces {
        painter.add(egui::Shape::convex_polygon(
            face.points.clone(),
            face.color,
            Stroke::new(0.5, Color32::BLACK),
        ));

        if let Some(face_idx) = highlight_face_index {
            let start = face_idx * 9;
            if face.sticker_index >= start && face.sticker_index < start + 9 {
                painter.add(egui::Shape::convex_polygon(
                    face.points.clone(),
                    Color32::TRANSPARENT,
                    Stroke::new(3.0, Color32::from_rgb(255, 140, 0)),
                ));
            }
        }

        draw_arrow_3d(
            painter,
            face.center_2d,
            face.arrow_end_2d,
            Color32::BLACK,
            VIEW3D_ARROW_WIDTH,
        );
    }
}

fn move_to_anim_params(mv: Move) -> (Vec3, i8, f32) {
    let pi_2 = std::f32::consts::FRAC_PI_2;
    match mv {
        Move::R => (Vec3::X, 1, -pi_2),
        Move::Rp => (Vec3::X, 1, pi_2),
        Move::R2 => (Vec3::X, 1, pi_2 * 2.0),
        Move::L => (Vec3::X, -1, pi_2),
        Move::Lp => (Vec3::X, -1, -pi_2),
        Move::L2 => (Vec3::X, -1, pi_2 * 2.0),
        Move::U => (Vec3::Y, 1, -pi_2),
        Move::Up => (Vec3::Y, 1, pi_2),
        Move::U2 => (Vec3::Y, 1, pi_2 * 2.0),
        Move::D => (Vec3::Y, -1, pi_2),
        Move::Dp => (Vec3::Y, -1, -pi_2),
        Move::D2 => (Vec3::Y, -1, pi_2 * 2.0),
        Move::F => (Vec3::Z, 1, -pi_2),
        Move::Fp => (Vec3::Z, 1, pi_2),
        Move::F2 => (Vec3::Z, 1, pi_2 * 2.0),
        Move::B => (Vec3::Z, -1, pi_2),
        Move::Bp => (Vec3::Z, -1, -pi_2),
        Move::B2 => (Vec3::Z, -1, pi_2 * 2.0),
        Move::M => (Vec3::X, 0, pi_2),
        Move::Mp => (Vec3::X, 0, -pi_2),
        Move::M2 => (Vec3::X, 0, pi_2 * 2.0),
        Move::E => (Vec3::Y, 0, pi_2),
        Move::Ep => (Vec3::Y, 0, -pi_2),
        Move::E2 => (Vec3::Y, 0, pi_2 * 2.0),
        Move::S => (Vec3::Z, 0, -pi_2),
        Move::Sp => (Vec3::Z, 0, pi_2),
        Move::S2 => (Vec3::Z, 0, pi_2 * 2.0),
        Move::X => (Vec3::X, 2, -90.0_f32.to_radians()),
        Move::Xp => (Vec3::X, 2, 90.0_f32.to_radians()),
        Move::X2 => (Vec3::X, 2, 180.0_f32.to_radians()),
        Move::Y => (Vec3::Y, 2, -90.0_f32.to_radians()),
        Move::Yp => (Vec3::Y, 2, 90.0_f32.to_radians()),
        Move::Y2 => (Vec3::Y, 2, 180.0_f32.to_radians()),
        Move::Z => (Vec3::Z, 2, -90.0_f32.to_radians()),
        Move::Zp => (Vec3::Z, 2, 90.0_f32.to_radians()),
        Move::Z2 => (Vec3::Z, 2, 180.0_f32.to_radians()),
    }
}

fn is_affected(pos: Vec3, axis: Vec3, layer: i8) -> bool {
    if layer == 2 {
        return true;
    }
    if axis == Vec3::X {
        (pos.x.round() as i8) == layer
    } else if axis == Vec3::Y {
        (pos.y.round() as i8) == layer
    } else if axis == Vec3::Z {
        (pos.z.round() as i8) == layer
    } else {
        false
    }
}

fn get_sticker_axes(normal: Vec3) -> (Vec3, Vec3) {
    let n = Vec3::new(normal.x.round(), normal.y.round(), normal.z.round());
    if n == Vec3::Y {
        (Vec3::X, -Vec3::Z)
    } else if n == -Vec3::Y {
        (Vec3::X, Vec3::Z)
    } else if n == -Vec3::X {
        (Vec3::Z, Vec3::Y)
    } else if n == Vec3::X {
        (-Vec3::Z, Vec3::Y)
    } else if n == Vec3::Z {
        (Vec3::X, Vec3::Y)
    } else if n == -Vec3::Z {
        (-Vec3::X, Vec3::Y)
    } else {
        (Vec3::X, Vec3::Y)
    }
}

fn normal_to_face(normal: Vec3) -> Face {
    let n = Vec3::new(normal.x.round(), normal.y.round(), normal.z.round());
    if n.y > 0.5 {
        Face::Up
    } else if n.y < -0.5 {
        Face::Down
    } else if n.x < -0.5 {
        Face::Left
    } else if n.x > 0.5 {
        Face::Right
    } else if n.z > 0.5 {
        Face::Front
    } else {
        Face::Back
    }
}

use crate::cube::{Color, Cube, Move};
use crate::gui::app::{AnimationState, EasingMode, SolverTask};
use crate::gui::renderer_3d::View3D;
use crate::history::History;
use crate::solver;
use crate::statistics::Statistics;
use std::sync::mpsc::Receiver;

use web_time::Instant;

/// キューブのコア状態（論理的な状態とビジネスロジック）
#[derive(Debug, Clone)]
pub struct CoreState {
    /// 現在のキューブの状態
    pub cube: Cube,
    /// 手動操作の履歴 (Undo/Redo用)
    pub history: History,
    /// 解法時間などの統計情報
    pub statistics: Statistics,
    /// ソルバーが見つけた解決手順（見つかっていない場合は `None`）
    pub solution: Option<Vec<Move>>,
    /// 解法開始前のキューブの状態（リセット用）
    pub solution_cube_state: Option<Cube>,
    /// 解法手順をたどる際の現在のステップ番号
    pub solution_step: usize,
}

impl Default for CoreState {
    fn default() -> Self {
        Self {
            cube: Cube::new(),
            history: History::new(),
            statistics: Statistics::new(),
            solution: None,
            solution_cube_state: None,
            solution_step: 0,
        }
    }
}

impl CoreState {
    /// 新しいコア状態を作成
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// 回転操作を適用
    pub fn apply_move(&mut self, mv: Move) {
        self.cube.apply_move(mv);
        self.history.push(mv);
        self.statistics.record_manual_move();
    }

    /// スクランブル
    pub fn scramble(&mut self, moves: usize) {
        self.cube.scramble(moves);
    }

    /// リセット
    pub fn reset(&mut self) {
        self.cube = Cube::new();
        self.history.clear();
        self.solution = None;
        self.solution_cube_state = None;
        self.solution_step = 0;
    }

    /// Undo
    pub fn undo(&mut self) -> Option<Move> {
        if let Some(inverse_mv) = self.history.undo() {
            self.cube.apply_move(inverse_mv);
            Some(inverse_mv)
        } else {
            None
        }
    }

    /// Redo
    pub fn redo(&mut self) -> Option<Move> {
        if let Some(mv) = self.history.redo() {
            self.cube.apply_move(mv);
            Some(mv)
        } else {
            None
        }
    }
}

/// ソルバー実行状態
pub struct SolverStateManager {
    /// 現在ソルバーが探索中かどうか
    pub solving: bool,
    /// 現在実行中のソルバータスクの種類
    pub solver_task: SolverTask,
    /// ソルバーの現在の探索進捗率 (0.0 - 1.0)
    pub solver_progress: f32,
    /// ソルバーの状態テキスト（「探索中...」など）
    pub solution_text: String,
    /// 探索開始時刻
    pub solving_start_time: Option<Instant>,
    /// 前回の探索にかかった時間（秒）
    pub last_solve_duration: Option<f32>,
    /// ソルバーがステッカーの向きを無視するかどうか
    pub ignore_orientation: bool,

    /// ソルバーからの結果受信用レシーバ
    pub solver_receiver: Option<Receiver<solver::Solution>>,
    /// ソルバーからの進捗受信用レシーバ
    pub progress_receiver: Option<Receiver<f32>>,

    /// WASM環境でのソルバー起動ペンディング状態
    #[cfg(target_arch = "wasm32")]
    pub pending_solver_start: Option<(SolverTask, bool, u8)>,

    /// WASM環境用: インクリメンタルソルバーの状態
    #[cfg(target_arch = "wasm32")]
    pub solver_state: Option<solver::SolverState>,
}

impl Default for SolverStateManager {
    fn default() -> Self {
        Self {
            solving: false,
            solver_task: SolverTask::Normal,
            solver_progress: 0.0,
            solution_text: String::new(),
            solving_start_time: None,
            last_solve_duration: None,
            ignore_orientation: false,
            solver_receiver: None,
            progress_receiver: None,
            #[cfg(target_arch = "wasm32")]
            pending_solver_start: None,
            #[cfg(target_arch = "wasm32")]
            solver_state: None,
        }
    }
}

impl SolverStateManager {
    /// 新しいソルバー状態を作成
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// ソルバーをキャンセル
    pub fn cancel(&mut self) {
        self.solving = false;
        self.solver_receiver = None;
        self.progress_receiver = None;
        self.solution_text.clear();
        #[cfg(target_arch = "wasm32")]
        {
            self.solver_state = None;
            self.pending_solver_start = None;
        }
    }
}

/// アニメーション状態の管理
pub struct AnimationStateManager {
    /// 現在実行中のアニメーション（実行されていない場合は `None`）
    pub animation: Option<AnimationState>,
    /// 未実行の操作キュー
    pub move_queue: Vec<(Move, Option<EasingMode>, Option<f32>)>,
    /// アニメーションの速度（1手あたりの秒数）
    pub animation_speed: f32,
    /// アニメーション完了後にステップ番号を更新するための保留値
    pub pending_solution_update: Option<isize>,
}

impl Default for AnimationStateManager {
    fn default() -> Self {
        Self {
            animation: None,
            move_queue: Vec::new(),
            animation_speed: 0.3,
            pending_solution_update: None,
        }
    }
}

impl AnimationStateManager {
    /// 新しいアニメーション状態を作成
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// 回転操作をキューに追加
    pub fn queue_move(&mut self, mv: Move) {
        self.move_queue.push((mv, None, None));
    }

    /// 複数の回転操作をキューに追加
    pub fn queue_moves(&mut self, moves: Vec<Move>) {
        for mv in moves {
            self.queue_move(mv);
        }
    }

    /// キューをクリア
    pub fn clear_queue(&mut self) {
        self.move_queue.clear();
        self.animation = None;
    }
}

/// UI表示状態
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ViewMode {
    TwoD,
    ThreeD,
    Both,
}

/// 入力状態（通常モード、スキャンモード）
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum InputState {
    Normal,
    Scanning { face_index: usize },
}

/// UI状態
pub struct UiState {
    /// 現在の表示モード（2D, 3D, Both）
    pub view_mode: ViewMode,
    /// 3Dビューのカメラ・倍率設定
    pub view_3d: View3D,
    /// モードに応じた入力状態（通常、スキャンモード）
    pub input_state: InputState,
    /// 6面スキャン入力中の色データ一時保持用
    pub input_buffer: [Option<Color>; 24],
    /// 入力パネルで選択されている色
    pub selected_input_color: Color,
    /// 入力中のエラーメッセージ（不正なパリティなど）
    pub input_error_message: String,
    /// 開発者用オプション：パリティチェック（物理的妥当性）をスキップするか
    pub skip_parity_check: bool,
}

