}

impl FaceCube {
    pub fn from_cube(cube: &Cube) -> Self {
        let mut f = [Color::White; 54];
        let face_map = [
            (Face::Up, 0),
            (Face::Right, 9),
            (Face::Front, 18),
            (Face::Down, 27),
            (Face::Left, 36),
            (Face::Back, 45),
        ];
        for (src_face, dst_offset) in face_map {
            let src_start = src_face.start_index();
            for i in 0..STICKERS_PER_FACE {
                f[dst_offset + i] = cube.stickers[src_start + i].color;
            }
        }
        Self { f }
    }
}

