impl SolverState {
    pub fn new(start_cube: &Cube, max_depth: usize, ignore_orientation: bool) -> Self {
        let rc = RawCube::from_cube(start_cube);
        Self {
            raw_cube: rc,
            initial_cube: start_cube.clone(),
            max_depth,
            ignore_orientation,
            solution: None,
            finished: false,
        }
    }
    pub fn error(&self) -> Option<String> {
        match &self.raw_cube {
            Ok(_) => None,
            Err(e) => Some(e.clone()),
        }
    }
    pub fn process_chunk(&mut self, _: usize) -> (usize, bool) {
        if self.finished {
            return (0, true);
        }
        let result = solve_internal(
            &self.initial_cube,
            self.max_depth,
            self.ignore_orientation,
            None,
        );
        self.solution = Some(result);
        self.finished = true;
        (1, true)
    }
    pub fn get_solution(&self) -> Option<Solution> {
        self.solution.clone()
    }
    pub fn estimate_progress(&self) -> f32 {
        if self.finished {
            1.0
        } else {
            0.5
        }
    }
}

use std::time::Duration;

use web_time::Instant;

/// アプリケーションの統計情報
#[derive(Debug, Clone)]
pub struct Statistics {
    /// 総解法試行回数
    pub total_solves: usize,

    /// 成功した解法回数
    pub successful_solves: usize,

    /// 総解法時間の累積
    pub total_solve_time: Duration,

    /// 最速解法時間
    pub best_solve_time: Option<Duration>,

    /// 手動操作の総回数
    pub total_manual_moves: usize,

    /// セッション開始時刻
    pub session_start: Instant,
}

impl Default for Statistics {
    fn default() -> Self {
        Self {
            total_solves: 0,
            successful_solves: 0,
            total_solve_time: Duration::ZERO,
            best_solve_time: None,
            total_manual_moves: 0,
            session_start: Instant::now(),
        }
    }
}

impl Statistics {
    /// 新しい統計情報を作成
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// 解法成功時に統計を更新
    pub fn record_solve(&mut self, solve_time: Duration) {
        self.total_solves += 1;
        self.successful_solves += 1;
        self.total_solve_time += solve_time;

        if let Some(best) = self.best_solve_time {
            if solve_time < best {
                self.best_solve_time = Some(solve_time);
            }
        } else {
            self.best_solve_time = Some(solve_time);
        }
    }

    /// 解法失敗時に統計を更新
    pub fn record_solve_failure(&mut self) {
        self.total_solves += 1;
    }

    /// 手動操作を記録
    pub fn record_manual_move(&mut self) {
        self.total_manual_moves += 1;
    }

    /// 平均解法時間を計算
    #[must_use]
    pub fn avg_solve_time(&self) -> Option<Duration> {
        if self.successful_solves > 0 {
            // successful_solvesは実用上数百程度なu32へのキャストは安全
            #[allow(clippy::cast_possible_truncation)]
            let count_u32 = self.successful_solves as u32;
            Some(self.total_solve_time / count_u32)
        } else {
            None
        }
    }

    /// 成功率を計算（0.0 ~ 1.0）
    #[must_use]
    pub fn success_rate(&self) -> f64 {
        if self.total_solves > 0 {
            // 統計値は実用上f64の52bit精度で十分
            #[allow(clippy::cast_precision_loss)]
            {
                self.successful_solves as f64 / self.total_solves as f64
            }
        } else {
            0.0
        }
    }

    /// セッション時間を取得
    #[must_use]
    pub fn session_duration(&self) -> Duration {
        self.session_start.elapsed()
    }
}

