    println!("Up center ori: {}", cube.stickers[Face::Up.start_index() + 4].orientation);
    for face in Face::all() {
        let ori = cube.stickers[face.start_index() + 4].orientation;
        if ori != 0 {
            println!("Face {:?} rotated: {}", face, ori);
        }
    }
}
